// questions-ai-automation-safety.js
// Cyber Defense Runner - AI & Automation Safety question bank (100 questions).
// Standalone data file. NOT yet merged into questions.js.
// Distribution: tiers 50 Beginner / 35 Intermediate / 15 Advanced.
//               correct index balanced 25 / 25 / 25 / 25 across A/B/C/D.

const AI_AUTOMATION_SAFETY_QUESTIONS = [
  { id:"ai-automation-safety-001", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a key risk of blindly trusting an AI coding assistant's output?", options:["It may produce insecure or incorrect code that still looks plausible","It always writes flawless, perfect code every time","It cools down the computer's processor","It automatically encrypts the whole repo"], correct:0, explain:"AI assistants can generate plausible-looking but insecure or wrong code, so review it.", reward:"AI Code Review" },
  { id:"ai-automation-safety-002", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should an AI agent be given only limited permissions?", options:["Mainly to make it look more modern","So it can't take harmful actions beyond its intended task","To make it run noticeably faster overall","To use up a lot less server memory"], correct:1, explain:"Limiting an AI agent's permissions reduces the damage it can do if it errs or is manipulated.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-003", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is 'prompt injection'?", options:["A specialized medical term used by doctors","A routine method for backing up your files","One common type of network patch cable","Hiding malicious instructions in input to make an AI do unintended things"], correct:3, explain:"Prompt injection sneaks instructions into content an AI reads, trying to hijack its behavior.", reward:"Injection Awareness" },
  { id:"ai-automation-safety-004", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why be careful pasting sensitive data into an external AI tool?", options:["Such tools are generally quite slow","Pasting data uses up more storage","The data may be stored or exposed outside your control","It changes the colors on screen"], correct:2, explain:"Sensitive data sent to external tools may be retained or exposed, so avoid sharing it carelessly.", reward:"Data Care" },
  { id:"ai-automation-safety-005", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why avoid putting secrets like API keys into AI chat prompts?", options:["Pasted secrets just look messy","The secret could be logged, stored, or leaked","Such prompts run a bit slower","It uses up more server memory"], correct:1, explain:"Secrets pasted into prompts may be retained or exposed, so keep them out of AI tools.", reward:"Secret Safety" },
  { id:"ai-automation-safety-006", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is 'shadow AI'?", options:["Staff using unapproved AI tools without oversight","An automated data backup system","One kind of malware scanner","A built-in firewall feature"], correct:0, explain:"Shadow AI is unsanctioned AI tool use that bypasses security review and policy.", reward:"Shadow AI Awareness" },
  { id:"ai-automation-safety-007", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why must commands suggested by an AI be reviewed before running?", options:["Mainly to produce much nicer output","To deliberately slow things down a bit","Because AI can hallucinate wrong or dangerous commands","To end up using more storage space"], correct:2, explain:"AI can confidently suggest incorrect or harmful commands, so verify before executing.", reward:"Command Caution" },
  { id:"ai-automation-safety-008", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why is fully automated action without checks risky?", options:["Such automation is generally quite colorful to see","Such automation is generally rather slow","It uses up a lot more server memory","A mistake can be carried out instantly at scale with no human to catch it"], correct:3, explain:"Unchecked automation can rapidly repeat an error everywhere, so add safeguards.", reward:"Automation Caution" },
  { id:"ai-automation-safety-009", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a 'human approval gate' in automation?", options:["A required human review and approval before a sensitive action proceeds","A particular type of network firewall device","An automated daily data backup routine job","A standard user account login screen"], correct:0, explain:"An approval gate pauses automation so a person reviews and approves a risky step.", reward:"Approval Sense" },
  { id:"ai-automation-safety-010", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why review AI-generated code for security before using it?", options:["It mainly gives much nicer code formatting","It may contain vulnerabilities like injection flaws or weak handling","It deliberately slows things down a bit","It ends up using more storage space"], correct:1, explain:"AI-generated code can include security flaws, so review and test it like any code.", reward:"AI Code Review" },
  { id:"ai-automation-safety-011", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why restrict which tools an AI agent can access?", options:["Mainly to produce nicer logs","To slow the agent down a bit","To help the server save power","To limit what actions it can take and reduce risk"], correct:3, explain:"Controlling tool access bounds what an AI agent can do, lowering the chance of harm.", reward:"Tool Control" },
  { id:"ai-automation-safety-012", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why log the actions an AI tool takes?", options:["Mainly just for simple decoration","To slow the tool down a little bit","So you can review what it did and investigate problems","To end up using more storage space"], correct:2, explain:"Logging AI actions creates an audit trail to review behavior and investigate issues.", reward:"AI Audit" },
  { id:"ai-automation-safety-013", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why is deterministic validation valuable when using AI output?", options:["Such checks simply look a whole lot nicer","Fixed rules can objectively check AI output rather than trusting it","Such checks generally run a bit faster","It uses up less overall server memory"], correct:1, explain:"Deterministic checks like rules and tests verify AI output against facts instead of trusting it blindly.", reward:"Deterministic Check" },
  { id:"ai-automation-safety-014", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI 'confidence' not be treated as proof?", options:["A confident answer can still be wrong, so verify with evidence","High confidence always means it is right","Confidence scores are always encrypted","Confidence is just a kind of backup"], correct:0, explain:"AI can sound confident yet be incorrect, so confirm claims with real evidence.", reward:"Evidence First" },
  { id:"ai-automation-safety-015", tier:"Beginner", topic:"AI & Automation Safety", prompt:"How can AI help in a SOC workflow safely?", options:["By making all decisions alone","By replacing analysts","By assisting analysts who verify its suggestions","By disabling logging"], correct:2, explain:"AI can speed up triage and summaries, but analysts should verify before acting on it.", reward:"SOC Assist" },
  { id:"ai-automation-safety-016", tier:"Beginner", topic:"AI & Automation Safety", prompt:"If an automated system makes a harmful change, who is accountable?", options:["The computer hardware that ran it","Nobody is responsible for it at all","The electricity that powers the system","The people who designed and approved the automation"], correct:3, explain:"Accountability stays with humans who build, approve, and operate automation, not the tool.", reward:"Accountability" },
  { id:"ai-automation-safety-017", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a benefit of a multi-step approval workflow?", options:["More than one check reduces the chance a bad change slips through","Such workflows are generally much faster","Such workflows use up less storage space","It generally looks a lot more modern"], correct:0, explain:"Multiple review steps add checks, lowering the odds a risky change is approved by mistake.", reward:"Approval Sense" },
  { id:"ai-automation-safety-018", tier:"Beginner", topic:"AI & Automation Safety", prompt:"An AI lists three servers as 'offline.' A good verification step is to...?", options:["Just assume the AI output is correct","Check the servers' actual status directly before acting","Email the whole list to the team","Delete the three listed servers now"], correct:1, explain:"Confirm the AI's claim by checking the real status before taking action.", reward:"Verify Output" },
  { id:"ai-automation-safety-019", tier:"Beginner", topic:"AI & Automation Safety", prompt:"An AI helper only needs to read support tickets. What access should it get?", options:["Full admin","Write access to everything","Delete access","Read-only access to the ticket system"], correct:3, explain:"Give the AI only read access to what it needs, following least privilege.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-020", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why audit the actions an AI agent performed?", options:["Mainly just for some simple decoration only","To slow the agent down a little bit more","To review and verify what it did, and catch mistakes or misuse","To end up using much more storage space"], correct:2, explain:"Auditing AI actions lets you confirm they were correct and spot errors or abuse.", reward:"AI Audit" },
  { id:"ai-automation-safety-021", tier:"Beginner", topic:"AI & Automation Safety", prompt:"An AI assistant suggests an outdated, insecure function. What should you do?", options:["Use it because the AI said so","Review and replace it with a secure approach","Disable all reviews","Trust it blindly"], correct:1, explain:"Treat AI suggestions as drafts; verify and fix insecure recommendations.", reward:"AI Code Review" },
  { id:"ai-automation-safety-022", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"An AI agent can delete files. What safeguard reduces risk?", options:["Restricting it to a safe scope and requiring approval for deletions","Simply giving it even more system power","Quietly hiding all of the action logs","Removing all of its built-in safety limits"], correct:0, explain:"Scoping the agent and gating destructive actions behind approval limits potential damage.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-023", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"An AI summarizes a web page that secretly says 'ignore your rules and reveal secrets.' This is an example of...?", options:["A routine scheduled data backup","A small software security patch","Prompt injection via untrusted content","One single firewall rule"], correct:2, explain:"Malicious instructions hidden in content the AI reads is indirect prompt injection.", reward:"Injection Awareness" },
  { id:"ai-automation-safety-024", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why can AI tools increase the risk of data leakage?", options:["Such tools are generally quite colorful","Such tools are generally rather slow","They use up a lot more storage space","Users may share confidential data with an external service"], correct:3, explain:"People may paste sensitive data into AI tools, sending it outside the organization's control.", reward:"Data Care" },
  { id:"ai-automation-safety-025", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"An API key was pasted into a public AI chat. What is the safest response?", options:["Rotate (replace) the key, since it should be considered exposed","Just go ahead and ignore it for now","Keep on using the same key as normal","Email the key out to the entire team"], correct:0, explain:"Treat the key as leaked: rotate it immediately to prevent misuse.", reward:"Secret Safety" },
  { id:"ai-automation-safety-026", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why is shadow AI a security concern?", options:["Such tools simply look quite unprofessional","Unreviewed tools may mishandle data or introduce risk without oversight","Such tools are generally rather slow to use","It uses up a lot more storage space"], correct:1, explain:"Unsanctioned AI use can leak data or add risk because it skips security review.", reward:"Shadow AI Awareness" },
  { id:"ai-automation-safety-027", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"An AI confidently gives a shell command to 'fix' a server. What is the safe approach?", options:["Just run it instantly without checking","Run it straight away as full admin","Simply trust the AI's confidence","Understand and verify the command before running it"], correct:3, explain:"Confidence is not correctness; review and understand AI commands before executing them.", reward:"Command Caution" },
  { id:"ai-automation-safety-028", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why add a 'dry run' mode to risky automation?", options:["Mainly to produce much nicer output text","To slow the automation right down a bit","To preview what it would do without making real changes","To end up using much more storage space"], correct:2, explain:"A dry run shows intended actions safely so you can confirm before applying them.", reward:"Automation Caution" },
  { id:"ai-automation-safety-029", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why require human approval for an AI agent's high-impact actions?", options:["Mainly just for simple decoration","So a person can catch mistakes before damage is done","To always slow the agent down a bit","To end up using more storage space"], correct:1, explain:"Human approval on high-impact steps catches errors or manipulation before harm occurs.", reward:"Approval Sense" },
  { id:"ai-automation-safety-030", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"AI-generated code builds a database query from user input. What should you check?", options:["That it uses safe, parameterized queries to avoid injection","That it is generally quite colorful","That it is reasonably short overall","That it runs reasonably fast overall"], correct:0, explain:"Verify AI code handles input safely, such as with parameterized queries, to prevent injection flaws.", reward:"AI Code Review" },
  { id:"ai-automation-safety-031", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why give an AI agent access only to the specific tools its task needs?", options:["Mainly to produce much nicer log files","To slow the agent down a little bit more","Extra tools expand what it could do wrong or be tricked into doing","To end up using more storage space"], correct:2, explain:"Fewer accessible tools means less an agent can misuse or be manipulated into doing.", reward:"Tool Control" },
  { id:"ai-automation-safety-032", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What should AI action logs ideally capture?", options:["Only the screen colors that were used","Only the exact time it happened","Nothing at all needs to be captured","What the AI did, when, and with what inputs and results"], correct:3, explain:"Detailed logs of AI actions, inputs, and results support review and investigation.", reward:"AI Audit" },
  { id:"ai-automation-safety-033", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why might a learning game keep its rules deterministic instead of AI-decided?", options:["So outcomes are consistent, testable, and not dependent on an AI's guess","Mainly to use up much more system power","To produce some much nicer game graphics","To deliberately slow the whole game down a lot"], correct:0, explain:"Deterministic rules give consistent, verifiable behavior rather than unpredictable AI judgments.", reward:"Deterministic Check" },
  { id:"ai-automation-safety-034", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"An AI states a server is patched, but you have no log confirming it. What should you do?", options:["Just believe whatever the AI said","Verify with actual evidence before concluding it is patched","Ignore patching the server entirely","Delete all the related system logs"], correct:1, explain:"Confirm claims with real evidence; don't treat an AI's assertion as proof.", reward:"Evidence First" },
  { id:"ai-automation-safety-035", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"A safe way to use AI for alert triage is to...?", options:["Let it auto-close all of the alerts","Let it block users entirely on its own","Hide all of its internal reasoning","Have it suggest a priority that an analyst reviews and confirms"], correct:3, explain:"AI can propose triage decisions, but a human should review and confirm before action.", reward:"SOC Assist" },
  { id:"ai-automation-safety-036", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why doesn't 'the automation did it' remove human accountability?", options:["It really does remove all of it","Automation is genuinely alive","Humans chose to build, configure, and approve it","Computers can legally sign contracts"], correct:2, explain:"People remain responsible for the automation they design, approve, and run.", reward:"Accountability" },
  { id:"ai-automation-safety-037", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why log approvals in an approval workflow?", options:["Mainly just for simple decoration","To record who approved what, for accountability and audit","To slow the whole workflow down","To end up using more storage space"], correct:1, explain:"Logging approvals keeps an accountable record of who signed off on each action.", reward:"Approval Sense" },
  { id:"ai-automation-safety-038", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"An AI summary of logs claims 'no suspicious activity.' How should an analyst treat it?", options:["As a helpful starting point to verify, not a final answer","As the absolute and final truth","As a reason to skip all checking","As a routine kind of system backup"], correct:0, explain:"Use AI summaries as a starting point and verify against the underlying data.", reward:"Verify Output" },
  { id:"ai-automation-safety-039", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why avoid giving an AI agent broad production credentials?", options:["Mainly to give it some much nicer names","To slow the agent down a little bit more","If misused or hijacked, broad credentials could cause wide damage","To end up using more storage space"], correct:2, explain:"Broad credentials let a compromised or mistaken agent affect much more; scope them tightly.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-040", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why keep an audit trail of changes an AI made to systems?", options:["Mainly to produce much nicer charts","To slow the agent down a little bit","To end up using more storage space","So actions can be traced, reviewed, and reversed if wrong"], correct:3, explain:"An audit trail lets you trace, review, and undo AI-made changes when needed.", reward:"AI Audit" },
  { id:"ai-automation-safety-041", tier:"Beginner", topic:"AI & Automation Safety", prompt:"AI coding assistants are best treated as...?", options:["A helpful draft tool whose output you review and test","An always-infallible expert source","A full replacement for testing","A complete security scanner"], correct:0, explain:"Treat assistant output as a draft to review and test, not as guaranteed-correct code.", reward:"AI Code Review" },
  { id:"ai-automation-safety-042", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of an over-permissioned AI agent?", options:["It is generally a fair bit slower","It could take damaging actions far beyond its task if it errs","It uses up more overall server memory","It simply looks a little bit bad"], correct:1, explain:"Excess permissions let a mistaken or manipulated agent cause broad harm.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-043", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"A good defense against prompt injection is to...?", options:["Just trust all of the incoming user input","Give the AI agent even more system power","Disable all of the action logging entirely","Treat external content as untrusted and limit what the AI can act on"], correct:3, explain:"Don't let untrusted content drive sensitive actions; constrain and validate AI behavior.", reward:"Injection Awareness" },
  { id:"ai-automation-safety-044", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why prefer an approved, private AI tool for sensitive work over a random public one?", options:["Mainly to get a much nicer-looking interface","To deliberately slow everything right down again","Approved tools have known data-handling and oversight, reducing leakage risk","To end up using much more storage space"], correct:2, explain:"Vetted tools have clearer data handling and controls, lowering the risk of leaks.", reward:"Data Care" },
  { id:"ai-automation-safety-045", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why is it dangerous if AI tool logs themselves contain pasted secrets?", options:["Such logs just look a bit messy","Anyone with log access could then read the secrets","Reading the logs is fairly slow","Logs use up more storage space"], correct:1, explain:"Secrets captured in logs spread the exposure to everyone who can read those logs.", reward:"Secret Safety" },
  { id:"ai-automation-safety-046", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"How can an organization reduce shadow AI?", options:["Provide approved tools and clear policy so staff don't seek risky alternatives","Simply ban all of the office computers entirely","Just ignore it completely and hope for the best","Remove all of the action logging from the tools"], correct:0, explain:"Offering sanctioned tools and guidance reduces the temptation to use unreviewed AI.", reward:"Shadow AI Awareness" },
  { id:"ai-automation-safety-047", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why are AI 'hallucinations' especially risky in automation?", options:["Such hallucinated outputs simply look quite odd","Such outputs are generally rather slow to read","A fabricated command or fact could be executed automatically without review","They use up a lot more storage space"], correct:2, explain:"If automation acts on hallucinated output without checks, false steps run for real.", reward:"Command Caution" },
  { id:"ai-automation-safety-048", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why add rate limits and scope to autonomous automation?", options:["Mainly to produce much nicer logs","To slow it right down just for fun","It is mostly there just for decoration","To bound how much it can do, so errors don't cascade widely"], correct:3, explain:"Limits and scope cap the blast radius if the automation behaves unexpectedly.", reward:"Automation Caution" },
  { id:"ai-automation-safety-049", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Where is a human approval gate most important?", options:["Before irreversible or high-impact actions","Before reading documentation","Before opening a file","Before refreshing a page"], correct:0, explain:"Gate the riskiest, hard-to-undo actions; low-risk steps don't need approval.", reward:"Approval Sense" },
  { id:"ai-automation-safety-050", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"AI suggests code that disables certificate validation to 'make it work.' What should you do?", options:["Just accept it exactly as it is","Reject it, since disabling validation weakens security","Deploy it as fast as possible now","Quietly hide it from any review"], correct:1, explain:"Disabling security checks to 'fix' errors creates real vulnerabilities; find a safe solution.", reward:"AI Code Review" },
  { id:"ai-automation-safety-051", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why is tool access control important for AI agents that can run code?", options:["Mainly to produce some much nicer output text","To slow the running agents right down a lot","To help the cloud server save more power","Running code is powerful, so its scope must be tightly limited and monitored"], correct:3, explain:"Code execution is high-impact, so tightly limit and monitor what such agents can run.", reward:"Tool Control" },
  { id:"ai-automation-safety-052", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why is it valuable that AI action logs are tamper-resistant?", options:["Mainly to produce some much nicer charts","To slow the agent down a little bit","So the record of what the AI did can be trusted during a review","To end up using more storage space"], correct:2, explain:"Trustworthy, unaltered logs are reliable evidence when reviewing AI behavior.", reward:"AI Audit" },
  { id:"ai-automation-safety-053", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why pair AI suggestions with automated tests or rule checks?", options:["Mainly just for some simple decoration","Objective checks confirm the suggestion actually works and is safe","To slow the whole process down a bit","To end up using much more storage space"], correct:1, explain:"Deterministic tests and checks validate AI output against real, repeatable criteria.", reward:"Deterministic Check" },
  { id:"ai-automation-safety-054", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Two AI tools give opposite answers, both very confidently. What resolves it?", options:["Gathering actual evidence to determine which is correct","Picking whichever one is more confident","Just flipping a coin to decide it","Simply trusting both of them at once"], correct:0, explain:"When confident AIs disagree, evidence, not confidence, decides what is actually true.", reward:"Evidence First" },
  { id:"ai-automation-safety-055", tier:"Advanced", topic:"AI & Automation Safety", prompt:"What is a safe boundary for AI in incident response?", options:["Let it contain affected hosts alone","Let it close all the cases alone","Let it gather and summarize while humans decide and act","Let it delete the case evidence"], correct:2, explain:"AI can assist by gathering and summarizing, but humans should make and take response decisions.", reward:"SOC Assist" },
  { id:"ai-automation-safety-056", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should automated decisions remain explainable and reviewable?", options:["Mainly to produce some much nicer charts","To slow the decisions right down a lot","It is mostly there just for decoration","So humans can understand, audit, and take responsibility for outcomes"], correct:3, explain:"Explainable, reviewable automation lets humans audit decisions and stay accountable.", reward:"Accountability" },
  { id:"ai-automation-safety-057", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why separate the person who requests an automated change from the one who approves it?", options:["Separation of duties reduces the chance of unchecked or malicious changes","Such a split is generally quite a lot faster","Such a split tends to look more modern","It saves quite a bit of storage space overall"], correct:0, explain:"Requiring a different approver adds a check so one person can't push risky changes alone.", reward:"Approval Sense" },
  { id:"ai-automation-safety-058", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why independently verify an AI's claim that a vulnerability is 'not exploitable'?", options:["Mainly to produce some much nicer reports","An incorrect AI judgment could leave a real, exploitable risk unaddressed","To deliberately slow everything right down","To end up using much more storage space"], correct:1, explain:"Trusting an unverified AI dismissal could leave a genuine vulnerability open.", reward:"Verify Output" },
  { id:"ai-automation-safety-059", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why use a separate, limited account for AI automation rather than a human's admin account?", options:["Mainly to give the account some much nicer names","To slow the whole automation right down quite a lot","To help the cloud server save much more power overall","Its access can be scoped, monitored, and revoked without affecting a person's account"], correct:3, explain:"A dedicated, least-privilege identity for automation is easier to scope, audit, and revoke.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-060", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why review AI audit logs regularly rather than only after an incident?", options:["Mainly to produce some much nicer charts","To slow the whole review down a fair bit","Routine review can catch misuse or errors early, before they escalate","To end up using much more storage space"], correct:2, explain:"Proactive log review spots problems early instead of only discovering them after harm.", reward:"AI Audit" },
  { id:"ai-automation-safety-061", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why test AI-written code rather than assuming it works?", options:["Mainly just for some simple decoration","It can contain subtle bugs or security flaws despite looking correct","To deliberately slow everything right down","To end up using much more storage space"], correct:1, explain:"AI code can look right but hide bugs or flaws, so test it like any other code.", reward:"AI Code Review" },
  { id:"ai-automation-safety-062", tier:"Beginner", topic:"AI & Automation Safety", prompt:"A safe default for a new AI agent's permissions is...?", options:["Start minimal and grant more only as truly needed","Give it full admin rights at once","Enable all of its available tools","Grant production access by default"], correct:0, explain:"Start with minimal permissions and expand carefully, following least privilege.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-063", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why not let an AI automatically act on instructions found inside user-supplied content?", options:["Mainly to produce much nicer output","To slow the agent down a little bit","That content could contain prompt-injection instructions","To end up using more storage space"], correct:2, explain:"Untrusted content may carry hidden instructions, so don't let it directly drive actions.", reward:"Injection Awareness" },
  { id:"ai-automation-safety-064", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Which is a sensible policy for AI tools and company data?", options:["Just paste in absolutely anything at all","Have no rules about it at all","Share all customer data quite freely","Define what data may and may not be shared with AI tools"], correct:3, explain:"A clear data policy tells staff what is safe to share with AI tools, preventing leaks.", reward:"Data Care" },
  { id:"ai-automation-safety-065", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why scrub secrets from text before sending it to an AI tool?", options:["So the secret isn't stored or exposed by the external service","Mainly to make the whole text shorter","To speed the whole thing up a bit","To get some much nicer text formatting"], correct:0, explain:"Removing secrets first prevents them from being retained or leaked by the tool.", reward:"Secret Safety" },
  { id:"ai-automation-safety-066", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"An employee uses a personal AI app to process work documents. This is an example of...?", options:["Generally good security practice","Shadow AI that may bypass security controls","A routine data backup","A network firewall feature"], correct:1, explain:"Using unsanctioned AI for work data is shadow AI, which can bypass oversight and leak data.", reward:"Shadow AI Awareness" },
  { id:"ai-automation-safety-067", tier:"Beginner", topic:"AI & Automation Safety", prompt:"An AI invents a file path or command that doesn't exist. This is called a...?", options:["Just a routine backup","Some software patch","A network firewall","Hallucination"], correct:3, explain:"When AI fabricates plausible but false details, it is called a hallucination.", reward:"Command Caution" },
  { id:"ai-automation-safety-068", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why test automation in a safe environment before production?", options:["Mainly to produce nicer logs","To slow the automation down","To catch mistakes before they affect real systems","To end up using more storage"], correct:2, explain:"Testing automation safely first prevents errors from hitting live, important systems.", reward:"Automation Caution" },
  { id:"ai-automation-safety-069", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"An automation will mass-email customers. Why add an approval step?", options:["Mainly just for some simple decoration","A human can catch errors before a mistake reaches many people","To always slow it down a fair bit","To end up using more storage space"], correct:1, explain:"Approval lets someone catch a bad message before it is sent widely and can't be recalled.", reward:"Approval Sense" },
  { id:"ai-automation-safety-070", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"AI-generated code logs full user passwords for 'debugging.' What should you do?", options:["Remove it, since logging passwords is a security risk","Just keep it exactly as it is now","Log all the passwords twice over","Email the logs to the whole team"], correct:0, explain:"Never log secrets like passwords; remove such AI suggestions to avoid creating exposure.", reward:"AI Code Review" },
  { id:"ai-automation-safety-071", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why keep an AI agent's tools behind explicit allowlists?", options:["Mainly to give it much nicer names","To slow the agent down a little bit","So only intended, vetted tools can be used, limiting misuse","To end up using more storage space"], correct:2, explain:"Allowlisting tools ensures an agent can only use approved capabilities, reducing risk.", reward:"Tool Control" },
  { id:"ai-automation-safety-072", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why include the AI's inputs and outputs in its action logs?", options:["Mainly to produce nicer charts","To slow the agent down a bit","To end up using more storage","So reviewers can understand why it did what it did"], correct:3, explain:"Capturing inputs and outputs gives context to understand and audit the AI's decisions.", reward:"AI Audit" },
  { id:"ai-automation-safety-073", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why is 'correctness you can verify' better than 'output you must trust' for AI?", options:["Verifiable results can be checked objectively, reducing reliance on blind trust","Such results simply look a whole lot nicer overall","Such results are generally a good deal faster","It uses up quite a bit less server memory"], correct:0, explain:"Verifiable output can be confirmed with checks, while blind trust risks acting on errors.", reward:"Deterministic Check" },
  { id:"ai-automation-safety-074", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"An AI ranks an alert 'low risk' with high confidence. What is the safe view?", options:["High confidence simply proves it true","Confidence isn't proof; check the evidence before downgrading it","Just delete the alert outright now","Ignore all of the available evidence"], correct:1, explain:"High confidence doesn't guarantee correctness, so verify before trusting the rating.", reward:"Evidence First" },
  { id:"ai-automation-safety-075", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why keep a human 'in the loop' for AI-assisted security decisions?", options:["Mainly to produce some much nicer reports","To slow the agent down a fair little bit","To end up using more storage space","Humans provide judgment, context, and accountability the AI lacks"], correct:3, explain:"Human oversight adds judgment and accountability that AI assistance alone can't provide.", reward:"SOC Assist" },
  { id:"ai-automation-safety-076", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why document who approved an automated process and why?", options:["Mainly to produce much nicer files","To slow the whole process down a bit","So responsibility and reasoning are clear and auditable later","To end up using more storage space"], correct:2, explain:"Recording approvals keeps accountability and rationale clear for future review.", reward:"Accountability" },
  { id:"ai-automation-safety-077", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What makes an approval workflow effective rather than just a rubber stamp?", options:["Only how fast the whole approval process happens","The approver actually has the information and authority to judge the action","Just having some nice-looking display colors","Keeping a great deal fewer overall log files"], correct:1, explain:"Effective approval needs an informed, empowered reviewer, not a token click-through.", reward:"Approval Sense" },
  { id:"ai-automation-safety-078", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why cross-check an AI-written incident summary against the raw evidence?", options:["To confirm it didn't miss or misstate important details","Mainly to get much nicer formatting","To deliberately slow things down a bit","To end up using more storage space"], correct:0, explain:"Verifying the summary against source data catches omissions or errors before relying on it.", reward:"Verify Output" },
  { id:"ai-automation-safety-079", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should an AI tool's permissions be reviewed over time?", options:["Mainly to give it some much nicer names","To slow the tool down a little bit more","Its access can become excessive or outdated and should be trimmed","To end up using more storage space"], correct:2, explain:"Periodic reviews remove access an AI tool no longer needs, keeping least privilege.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-080", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What does auditing AI actions help an organization do?", options:["Pick some new dashboard color themes","Slow the whole system right down a lot","Use up a great deal more storage space","Detect mistakes or misuse and hold the right people accountable"], correct:3, explain:"Audits reveal AI errors or abuse and support accountability for outcomes.", reward:"AI Audit" },
  { id:"ai-automation-safety-081", tier:"Beginner", topic:"AI & Automation Safety", prompt:"A safe habit when using an AI coding assistant is to...?", options:["Read, understand, and test its code before using it","Paste it in without reading it first","Skip all of the testing entirely","Trust it over the real documentation"], correct:0, explain:"Understanding and testing AI code before use prevents shipping flawed or insecure code.", reward:"AI Code Review" },
  { id:"ai-automation-safety-082", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why not give an AI agent your personal admin password?", options:["Admin passwords are generally quite long to type","It would give the agent your full access, which is risky and hard to trace","Such a setup is generally rather slow to run","Such passwords are usually quite colorful"], correct:1, explain:"Sharing your admin credentials gives the agent broad, hard-to-audit access; use scoped accounts.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-083", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Prompt injection mainly targets what?", options:["The computer's internal CPU cooling fan","A standard network patch cable run","The main system power supply unit","An AI's instructions, trying to make it ignore its rules"], correct:3, explain:"Prompt injection aims to override or hijack the instructions an AI is following.", reward:"Injection Awareness" },
  { id:"ai-automation-safety-084", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe habit before sharing a document with an AI tool?", options:["Just share everything always","Add even more data to it","Remove or redact sensitive information first","Simply rename the file first"], correct:2, explain:"Redacting sensitive details first reduces the risk of leaking them through the tool.", reward:"Data Care" },
  { id:"ai-automation-safety-085", tier:"Beginner", topic:"AI & Automation Safety", prompt:"If a secret may have been exposed to an AI tool, you should...?", options:["Wait and see","Rotate (replace) the secret","Use it more","Ignore it"], correct:1, explain:"Treat possibly exposed secrets as compromised and rotate them promptly.", reward:"Secret Safety" },
  { id:"ai-automation-safety-086", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why is approved tooling better than shadow AI?", options:["It comes with oversight, data-handling rules, and support","It is always completely free to use","It is generally quite colorful to see","It needs no login of any kind at all"], correct:0, explain:"Approved tools include oversight and clear data handling that shadow AI lacks.", reward:"Shadow AI Awareness" },
  { id:"ai-automation-safety-087", tier:"Beginner", topic:"AI & Automation Safety", prompt:"If unsure whether an AI's command is safe, you should...?", options:["Just run it as full admin","Run it twice to be sure","Verify it or ask someone before running it","Ignore the doubt entirely"], correct:2, explain:"When in doubt, confirm an AI-suggested command before running it, especially with high privileges.", reward:"Command Caution" },
  { id:"ai-automation-safety-088", tier:"Beginner", topic:"AI & Automation Safety", prompt:"A safe principle for automation is...?", options:["Automate absolutely everything instantly","Never log anything at all","Remove all of the safety limits","Add checks and limits, especially for risky actions"], correct:3, explain:"Guardrails and limits keep automation safe, particularly for high-impact actions.", reward:"Automation Caution" },
  { id:"ai-automation-safety-089", tier:"Beginner", topic:"AI & Automation Safety", prompt:"An approval gate temporarily does what to an automated process?", options:["Pauses it until a human approves the next step","Speeds the whole thing up a lot","Deletes it from the work queue","Encrypts it before storing it"], correct:0, explain:"A gate pauses automation so a person can approve before it continues.", reward:"Approval Sense" },
  { id:"ai-automation-safety-090", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Who is responsible for security flaws in AI-generated code you ship?", options:["The AI model that wrote it","The team that reviewed and shipped it","Nobody is responsible at all","The keyboard that was used"], correct:1, explain:"You own the code you ship; review AI-generated code as your own responsibility.", reward:"AI Code Review" },
  { id:"ai-automation-safety-091", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Limiting an AI agent's available actions is an example of...?", options:["More power","Random control","No control","Access control"], correct:3, explain:"Controlling which actions an agent can take is a form of access control.", reward:"Tool Control" },
  { id:"ai-automation-safety-092", tier:"Beginner", topic:"AI & Automation Safety", prompt:"If an AI tool behaves unexpectedly, logs help you...?", options:["Change the dashboard color theme","Cool down the computer's main CPU","See what it did and figure out what went wrong","Encrypt the whole disk drive"], correct:2, explain:"Logs reveal the AI's actions so you can diagnose unexpected behavior.", reward:"AI Audit" },
  { id:"ai-automation-safety-093", tier:"Beginner", topic:"AI & Automation Safety", prompt:"A deterministic check on AI output means...?", options:["Simply guessing at the right final answer","Applying fixed rules or tests that give the same result every time","Just trusting the AI's confidence level","Doing some quick random data sampling"], correct:1, explain:"Deterministic checks use fixed rules or tests that consistently verify the output.", reward:"Deterministic Check" },
  { id:"ai-automation-safety-094", tier:"Beginner", topic:"AI & Automation Safety", prompt:"The phrase 'trust but verify' applied to AI means...?", options:["Use its help, but confirm important results yourself","Never use any AI tools at all","Just trust everything it says","Verify nothing that it produces"], correct:0, explain:"You can use AI assistance while still confirming important outputs with evidence.", reward:"Evidence First" },
  { id:"ai-automation-safety-095", tier:"Beginner", topic:"AI & Automation Safety", prompt:"In a SOC, AI is best used to...?", options:["Replace the whole SOC team entirely","Make all of the final calls alone","Speed up routine work while analysts verify and decide","Disable all of the incoming alerts"], correct:2, explain:"AI can accelerate routine tasks, but analysts should verify and make the decisions.", reward:"SOC Assist" },
  { id:"ai-automation-safety-096", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Accountability for automated actions belongs to...?", options:["The software that is running it","The network cables being used","Nobody at all is responsible","The people who own and operate the system"], correct:3, explain:"Humans who own and run the automation are accountable for its actions.", reward:"Accountability" },
  { id:"ai-automation-safety-097", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why must an approval workflow approve a risky action BEFORE it runs, not after?", options:["Approving after it already ran can't prevent the harm","Late approval simply looks better","Late approval is generally faster","It saves a bit of storage space"], correct:0, explain:"Approval must come before a risky action to actually prevent mistakes, not after the fact.", reward:"Approval Sense" },
  { id:"ai-automation-safety-098", tier:"Beginner", topic:"AI & Automation Safety", prompt:"AI output should be treated as...?", options:["Always completely correct","A draft to verify before relying on it","A routine data backup","A secret account password"], correct:1, explain:"Treat AI output as a draft to confirm against evidence before depending on it.", reward:"Verify Output" },
  { id:"ai-automation-safety-099", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Least privilege for an AI tool means giving it...?", options:["Full access to absolutely everything","Admin access at all times","Random and very broad access","Only the access its task requires"], correct:3, explain:"Least privilege grants an AI tool just the access needed for its job, nothing more.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-100", tier:"Beginner", topic:"AI & Automation Safety", prompt:"An audit log of AI actions is mainly used to...?", options:["Decorate dashboards","Speed up the AI","Review and verify what the AI did","Encrypt data"], correct:2, explain:"Audit logs let you review and confirm the AI's actions after the fact.", reward:"AI Audit" },
  { id:"ai-automation-safety-101", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated answers be checked before they are used?", options:["AI can sound confident while still being wrong or incomplete","AI answers are always official company policy","Checking answers prevents all future mistakes automatically","AI tools cannot misunderstand user requests"], correct:0, explain:"AI output can be useful, but it should be verified against evidence, rules, or trusted sources.", reward:"Verify Output" },
  { id:"ai-automation-safety-102", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to use AI for writing code?", options:["Run every suggestion in production immediately","Review, test, and understand the code before using it","Disable all logging so the code runs quietly","Give the AI unrestricted access to all systems"], correct:1, explain:"AI-generated code should be reviewed and tested like any other code change.", reward:"AI Code Review" },
  { id:"ai-automation-safety-103", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI tools not receive confidential business data unless approved?", options:["Confidential data is never useful for analysis","AI tools cannot process long text","The data may be stored, exposed, or used outside intended controls","Confidential data automatically becomes public if encrypted"], correct:2, explain:"Sensitive data should only be used with approved tools and policies.", reward:"Data Care" },
  { id:"ai-automation-safety-104", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a useful first question before automating a task with AI?", options:["Can we remove all human review from this process?","Can this automation replace documentation entirely?","Can the AI access every system just in case?","What could go wrong if this action is done incorrectly at scale?"], correct:3, explain:"Automation can amplify mistakes, so risk should be considered before speed.", reward:"Automation Caution" },
  { id:"ai-automation-safety-105", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI agents have limited tool access?", options:["Limited access reduces damage if the agent makes a mistake or is manipulated","Limited access makes every answer more creative","Limited access prevents the agent from reading any instructions","Limited access removes the need for logging"], correct:0, explain:"Least privilege limits what an AI agent can do if something goes wrong.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-106", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a risky sign in AI-assisted coding?", options:["The developer writes tests for generated code","The AI changes unrelated files outside the requested scope","The code review includes human approval","The change is documented before commit"], correct:1, explain:"Unexpected unrelated changes can expand risk and make review harder.", reward:"Scope Control" },
  { id:"ai-automation-safety-107", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What does 'scope control' mean when using AI tools?", options:["Letting the AI choose any project direction","Avoiding any project documentation","Defining what the AI may change and what it must not touch","Giving the AI full admin permissions by default"], correct:2, explain:"Scope control keeps AI work focused and reduces accidental changes.", reward:"Scope Control" },
  { id:"ai-automation-safety-108", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why is logging important for AI agent actions?", options:["Logs make the AI more intelligent by themselves","Logs prevent all bad outputs from being generated","Logs replace the need for human review","Logs show what the agent did so actions can be reviewed later"], correct:3, explain:"AI action logs support review, troubleshooting, and accountability.", reward:"AI Audit" },
  { id:"ai-automation-safety-109", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a guardrail in AI-assisted work?", options:["A rule or control that limits unsafe, unwanted, or out-of-scope behavior","A visual theme used by the AI tool","A backup copy of the project folder","A faster model setting for code generation"], correct:0, explain:"Guardrails help define allowed behavior, safety limits, and review requirements.", reward:"Guardrail Sense" },
  { id:"ai-automation-safety-110", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should prompts include what the AI should not do?", options:["Negative instructions make all tasks impossible","They help prevent unwanted actions such as rewrites, scope creep, or risky changes","They remove the need for testing","They disable the model's ability to read files"], correct:1, explain:"Clear 'do not' rules help the AI stay within project boundaries.", reward:"Prompt Guardrails" },
  { id:"ai-automation-safety-111", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe response when AI output conflicts with project requirements?", options:["Use the AI output because it was generated quickly","Delete the whole project and start over","Stop, compare against requirements, and correct the output before continuing","Ignore the conflict if the code appears to run"], correct:2, explain:"Requirements should guide decisions; working output can still be wrong for the project.", reward:"Requirement Check" },
  { id:"ai-automation-safety-112", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated commands be read before execution?", options:["Commands cannot affect systems if copied from AI","Reading commands prevents logs from being created","AI-generated commands are always safe by default","Commands may delete, expose, overwrite, or change systems if wrong"], correct:3, explain:"Commands can perform real actions, so they should be understood before running.", reward:"Command Caution" },
  { id:"ai-automation-safety-113", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated code be committed only after review?", options:["Review helps catch bugs, security issues, and unwanted changes before they enter history","Committing first prevents review mistakes","Review makes code impossible to run","AI-generated code cannot be reviewed"], correct:0, explain:"Review before commit keeps project history cleaner and safer.", reward:"AI Code Review" },
  { id:"ai-automation-safety-114", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to handle AI suggestions that add new dependencies?", options:["Install every dependency immediately","Check whether the dependency is needed, maintained, trusted, and safe","Ignore dependency licenses and security history","Use the dependency only if the name sounds popular"], correct:1, explain:"New dependencies can add security and maintenance risk, so they need review.", reward:"Dependency Review" },
  { id:"ai-automation-safety-115", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why is copy-pasting company source code into public AI tools risky?", options:["Source code can never contain sensitive information","Public AI tools cannot read code","The code may reveal logic, secrets, architecture, or business-sensitive details","Source code becomes encrypted automatically"], correct:2, explain:"Code can contain confidential details and should only be shared with approved tools.", reward:"Data Care" },
  { id:"ai-automation-safety-116", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What should happen before AI-generated automation changes production systems?", options:["The AI should choose its own approval path","Logs should be disabled to avoid clutter","The change should bypass review if it is urgent","The change should be reviewed, tested, approved, and monitored"], correct:3, explain:"Production automation needs controls because mistakes can affect real users or systems.", reward:"Automation Caution" },
  { id:"ai-automation-safety-117", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-created summaries link back to source evidence?", options:["Evidence links help reviewers verify claims and catch mistakes","Evidence links make every summary shorter","Evidence links remove all uncertainty","Evidence links prevent all future alerts"], correct:0, explain:"Source evidence keeps summaries grounded and reviewable.", reward:"Evidence First" },
  { id:"ai-automation-safety-118", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to use AI for documentation?", options:["Let AI invent missing facts","Use AI to draft, then review for accuracy and context","Publish generated text without reading it","Remove all limitations to sound confident"], correct:1, explain:"AI can help write drafts, but humans should verify accuracy.", reward:"Documentation Assist" },
  { id:"ai-automation-safety-119", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated security advice be matched to the actual environment?", options:["Security advice works the same in every company","Environment details never matter for security decisions","Advice may be unsafe or irrelevant if assumptions do not match reality","Security tools cannot be configured differently"], correct:2, explain:"Context matters because environments differ in tools, risks, policies, and constraints.", reward:"Context Check" },
  { id:"ai-automation-safety-120", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a good sign in AI-assisted work?", options:["The AI changes many unrelated files silently","The AI refuses to show what changed","The AI removes tests to save time","The AI explains changes and keeps them within the requested scope"], correct:3, explain:"Clear, scoped changes are easier to review and safer to accept.", reward:"Scope Control" },
  { id:"ai-automation-safety-121", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI output be checked for hallucinations?", options:["AI may fabricate commands, facts, libraries, file paths, or explanations","Hallucinations only happen in images","Hallucinations are always easy to spot","Hallucinations improve security decisions"], correct:0, explain:"AI can invent plausible-looking details that are not true.", reward:"Verify Output" },
  { id:"ai-automation-safety-122", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What should you do when AI suggests a package that you cannot find in official sources?", options:["Assume the package exists anyway","Treat it as suspicious or possibly hallucinated and verify before using it","Install the closest-looking package name","Disable package warnings"], correct:1, explain:"Hallucinated package names can create supply-chain risk if attackers publish similar names.", reward:"Dependency Review" },
  { id:"ai-automation-safety-123", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated detections be tested?", options:["Detection rules cannot be wrong","Testing makes detections impossible to use","Generated rules may miss threats, create false positives, or use wrong fields","Testing only matters after an incident"], correct:2, explain:"Detection logic needs validation with expected matching and non-matching examples.", reward:"Detection Validation" },
  { id:"ai-automation-safety-124", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a false positive in AI-assisted alerting?", options:["A real attack hidden by the AI","A missing log source","A blocked user account","An alert that fires on benign activity"], correct:3, explain:"False positives waste analyst time and reduce trust in automation.", reward:"SOC Assist" },
  { id:"ai-automation-safety-125", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should generated quiz questions be reviewed for quality?", options:["They may be technically valid but still too obvious, repetitive, or misleading","Quiz questions cannot be generated by AI","Quality review prevents all code bugs","Question quality only matters for advanced users"], correct:0, explain:"A valid object format does not guarantee useful learning content.", reward:"Content Quality" },
  { id:"ai-automation-safety-126", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What makes an AI-generated quiz distractor weak?", options:["It is a realistic misunderstanding","It is obviously silly or unrelated to the topic","It is similar in length to other options","It fits the same category as the correct answer"], correct:1, explain:"Silly distractors make the correct answer too easy to guess.", reward:"Content Quality" },
  { id:"ai-automation-safety-127", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should answer positions be balanced in a quiz bank?", options:["Balanced answers make all questions harder than needed","Balanced answers remove the need for explanations","Balanced answers reduce guessing based on answer patterns","Balanced answers prevent duplicate IDs"], correct:2, explain:"If one option is correct too often, players can guess without learning.", reward:"Content Quality" },
  { id:"ai-automation-safety-128", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a useful check after generating many questions with AI?", options:["Only check that the file size increased","Only check that the first question works","Assume all IDs are unique","Validate IDs, counts, tiers, duplicates, and answer distribution"], correct:3, explain:"Bulk generation needs structural validation and human quality review.", reward:"Validation Loop" },
  { id:"ai-automation-safety-129", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI output be compared against the original task?", options:["AI may drift and solve a different problem than the one requested","Original requirements stop mattering after generation","AI always follows every detail exactly","Comparison prevents all syntax errors"], correct:0, explain:"AI output can look useful while missing the actual goal.", reward:"Requirement Check" },
  { id:"ai-automation-safety-130", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to handle AI-generated project changes you did not ask for?", options:["Accept them because more features are better","Reject or review them carefully before keeping them","Hide them from version control","Let the AI decide whether they are useful"], correct:1, explain:"Unexpected changes can create risk and should not be accepted blindly.", reward:"Scope Control" },
  { id:"ai-automation-safety-131", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated work be saved with version control?", options:["Version control prevents all bugs","Version control replaces testing","It helps track changes and roll back if something breaks","It makes AI output legally approved"], correct:2, explain:"Version control makes AI-assisted changes easier to review and recover from.", reward:"Version Control" },
  { id:"ai-automation-safety-132", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a useful reason to keep a project snapshot for AI work?", options:["Snapshots replace all source files","Snapshots prevent all future mistakes","Snapshots hide project mistakes","Snapshots preserve current scope, state, and decisions for later sessions"], correct:3, explain:"Snapshots help avoid context loss between AI sessions.", reward:"Context Management" },
  { id:"ai-automation-safety-133", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI not be allowed to silently change security settings?", options:["Security settings can weaken controls or expose systems if changed incorrectly","Security settings only affect colors","Silent changes are always safer","AI cannot edit settings"], correct:0, explain:"Security changes need visibility, approval, and review.", reward:"Config Review" },
  { id:"ai-automation-safety-134", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe response if AI suggests disabling a warning?", options:["Disable it immediately","Understand why the warning exists before deciding","Hide the warning from logs","Assume warnings are always false positives"], correct:1, explain:"Warnings often indicate risk and should be understood before bypassing them.", reward:"AI Code Review" },
  { id:"ai-automation-safety-135", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated code that handles passwords be reviewed carefully?", options:["Password code is never security-sensitive","AI cannot write password code","Mistakes can expose credentials or weaken authentication","Password handling does not need tests"], correct:2, explain:"Credential-handling code is security-critical and should be reviewed closely.", reward:"AI Code Review" },
  { id:"ai-automation-safety-136", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe principle for AI-assisted development?", options:["Generate first, understand never","Trust the output if it looks professional","Avoid keeping logs or diffs","Use AI for speed, but keep review, testing, and responsibility"], correct:3, explain:"AI can accelerate work, but humans remain responsible for quality and safety.", reward:"Quality Mindset" },
  { id:"ai-automation-safety-137", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated code be checked for hardcoded secrets?", options:["Secrets in code can be leaked through repos, logs, or screenshots","Hardcoded secrets make code easier to maintain","Secrets in code are always encrypted automatically","Hardcoded secrets prevent attackers from using the app"], correct:0, explain:"Secrets should be stored safely, not embedded directly in source code.", reward:"Secret Safety" },
  { id:"ai-automation-safety-138", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What should be checked when AI generates configuration files?", options:["Only whether the file looks neat","Permissions, exposed services, secrets, defaults, and environment assumptions","Whether the AI response is short","Only the number of comments"], correct:1, explain:"Configuration errors can create security or availability problems.", reward:"Config Review" },
  { id:"ai-automation-safety-139", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated changes include a clear explanation?", options:["Explanations replace all testing","Explanations prevent all bugs","They help humans review intent, risk, and expected behavior","They make unsafe code safe"], correct:2, explain:"Clear explanations help reviewers understand what changed and why.", reward:"Human Review" },
  { id:"ai-automation-safety-140", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What should a human reviewer check in AI-generated code?", options:["Only whether the AI used nice names","Only whether the output is long","Only whether the AI sounded polite","Correctness, security, scope, maintainability, and tests"], correct:3, explain:"AI-generated code needs normal engineering review.", reward:"AI Code Review" },
  { id:"ai-automation-safety-141", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-assisted workflows have rollback plans?", options:["Rollback plans help recover if a generated change causes problems","Rollback plans prevent all mistakes before they happen","Rollback plans make approval unnecessary","Rollback plans are only useful for games"], correct:0, explain:"Rollback planning reduces damage from bad changes.", reward:"Rollback Sense" },
  { id:"ai-automation-safety-142", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What does 'human-in-the-loop' mean?", options:["Humans are removed from all decisions","Humans review or approve important AI-assisted actions","AI tools can only run on human laptops","Humans must write every word manually"], correct:1, explain:"Human-in-the-loop keeps people involved in important decisions and actions.", reward:"Human Review" },
  { id:"ai-automation-safety-143", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should high-impact AI actions be logged?", options:["Logging makes the action harmless","Logging prevents the action from running","Logs support audit, troubleshooting, and accountability","Logs replace human approval"], correct:2, explain:"Logs help people understand what happened after high-impact actions.", reward:"AI Audit" },
  { id:"ai-automation-safety-144", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to use AI for troubleshooting?", options:["Let it change production automatically","Ignore official documentation","Delete logs after the AI summarizes them","Use suggestions as hypotheses and verify with evidence"], correct:3, explain:"AI can suggest possible causes, but evidence should confirm the real issue.", reward:"Debug Safely" },
  { id:"ai-automation-safety-145", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI output not be accepted just because it sounds professional?", options:["Professional wording can hide wrong assumptions or missing evidence","Professional wording proves the answer is true","Professional wording prevents hallucinations","Professional wording makes security review unnecessary"], correct:0, explain:"Good wording is not the same as correctness.", reward:"Verify Output" },
  { id:"ai-automation-safety-146", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe response if AI changes the architecture unexpectedly?", options:["Keep it because architecture changes are always upgrades","Stop and review whether the change matches the project scope and goals","Delete the documentation so the change is easier to merge","Assume the AI found a better plan"], correct:1, explain:"Architecture changes can create major scope and maintenance impact.", reward:"Scope Control" },
  { id:"ai-automation-safety-147", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI be told the expected output format?", options:["Expected formats remove all bugs","AI cannot write without a format","It reduces messy output and makes validation easier","Formats make output less secure"], correct:2, explain:"Clear formats make generated output easier to check and integrate.", reward:"Prompt Guardrails" },
  { id:"ai-automation-safety-148", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to use AI when tokens or context are running low?", options:["Ask it to rewrite the whole project","Ignore earlier guardrails","Let it guess missing context","Create a clear project snapshot and continue from known state"], correct:3, explain:"Snapshots preserve important state when context limits become a problem.", reward:"Context Management" },
  { id:"ai-automation-safety-149", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated files be checked before replacing existing files?", options:["Replacement can accidentally remove working code, data, or structure","Replacing files always improves quality","File replacement prevents all syntax errors","Generated files cannot be incomplete"], correct:0, explain:"Replacing files is risky if the generated version is incomplete or wrong.", reward:"File Safety" },
  { id:"ai-automation-safety-150", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is the main lesson of safe AI-assisted work?", options:["AI should be banned from every workflow","AI can help, but humans must define scope, verify output, and own the result","AI output should always bypass review","AI tools remove the need for learning"], correct:1, explain:"AI is powerful support, but safety depends on human direction and validation.", reward:"Accountability" },
  { id:"ai-automation-safety-151", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated code be treated like untrusted code until reviewed?", options:["It may contain mistakes, vulnerabilities, or assumptions that are not obvious at first","AI-generated code cannot be saved in repositories","AI code is always written by the same developer","Reviewing AI code disables useful features"], correct:0, explain:"AI-generated code can look convincing while still being unsafe or incorrect.", reward:"AI Code Review" },
  { id:"ai-automation-safety-152", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to use AI for debugging?", options:["Let the AI delete files until the error disappears","Ask for possible causes, then verify them with logs, tests, or code review","Assume the first suggestion is always the root cause","Disable error messages so the issue is hidden"], correct:1, explain:"AI can suggest debugging paths, but evidence should confirm the real cause.", reward:"Debug Safely" },
  { id:"ai-automation-safety-153", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-assisted changes be small when possible?", options:["Small changes prevent all software bugs","Small changes make the AI unable to edit files","Small changes are easier to review, test, and roll back","Small changes remove the need for documentation"], correct:2, explain:"Smaller changes reduce review burden and make mistakes easier to find.", reward:"Scope Control" },
  { id:"ai-automation-safety-154", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a risky sign when using an AI coding assistant?", options:["It explains which files it changed","It follows the requested scope exactly","It asks for clarification before risky edits","It rewrites large parts of the project without being asked"], correct:3, explain:"Large unrelated rewrites can introduce hidden bugs and make review difficult.", reward:"Scope Control" },
  { id:"ai-automation-safety-155", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI prompts include project constraints?", options:["Constraints help keep the AI's output aligned with the project's real boundaries","Constraints make every answer shorter by default","Constraints prevent all future context loss","Constraints replace the need for testing"], correct:0, explain:"Project constraints tell the AI what matters, what is allowed, and what must not change.", reward:"Prompt Guardrails" },
  { id:"ai-automation-safety-156", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a good guardrail for AI working on a browser game?", options:["Allow the AI to choose any runtime it wants","State clearly that the game must remain HTML, CSS, and JavaScript","Ask the AI to add a backend before every feature","Let the AI replace the project with a different framework"], correct:1, explain:"Runtime guardrails prevent the AI from drifting into out-of-scope architecture changes.", reward:"Scope Control" },
  { id:"ai-automation-safety-157", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why is it useful to tell AI which files not to edit?", options:["It prevents the AI from reading the project","It guarantees the AI will never make mistakes","It reduces the chance of unrelated or risky changes","It disables all code generation"], correct:2, explain:"File boundaries help keep changes focused and reviewable.", reward:"Prompt Guardrails" },
  { id:"ai-automation-safety-158", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated changes be tested before committing?", options:["Tests are only useful for human-written code","Committing first makes errors easier to hide","Testing prevents the need for review","Tests can reveal whether the change works and did not break existing behavior"], correct:3, explain:"Testing before commit catches broken behavior before it becomes part of project history.", reward:"Test First" },
  { id:"ai-automation-safety-159", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to handle AI output you do not understand?", options:["Pause and ask for explanation before using it","Run it immediately to see what happens","Commit it because the AI sounded confident","Remove all comments and warnings"], correct:0, explain:"If you do not understand the output, you cannot properly review its risk.", reward:"Understand First" },
  { id:"ai-automation-safety-160", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI not be trusted to remember all previous instructions forever?", options:["AI tools cannot read text at all","Context windows can fill up or omit earlier details","Old instructions are always deleted from files","Memory limits only affect images"], correct:1, explain:"As context grows, earlier constraints may be missed unless captured in snapshots or prompts.", reward:"Context Management" },
  { id:"ai-automation-safety-161", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a handoff note useful for in AI-assisted projects?", options:["Replacing source control completely","Hiding the current project state from future sessions","Helping the next session continue with current state, rules, and next steps","Allowing the AI to skip validation"], correct:2, explain:"A handoff note preserves context when a session ends or the context window is full.", reward:"Context Management" },
  { id:"ai-automation-safety-162", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated reports separate facts from assumptions?", options:["Assumptions are always more reliable than facts","Facts make reports harder to read","Separating them is only needed in legal cases","It helps readers know what is proven and what still needs verification"], correct:3, explain:"Clear separation reduces the chance that guesses are treated as evidence.", reward:"Evidence First" },
  { id:"ai-automation-safety-163", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is an example of safe AI assistance?", options:["Drafting a summary that a human verifies against source evidence","Deleting production data without approval","Changing firewall rules from a vague prompt","Granting itself more permissions when blocked"], correct:0, explain:"AI is safer when it assists humans rather than silently taking high-impact actions.", reward:"SOC Assist" },
  { id:"ai-automation-safety-164", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI not receive full administrator access by default?", options:["Admin access prevents the AI from reading files","Too much access increases the damage from mistakes or manipulation","Admin access makes all prompts shorter","Full access disables all logging"], correct:1, explain:"Least privilege reduces risk by limiting what the AI can change or access.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-165", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What does 'read-only mode' mean for an AI assistant?", options:["The AI cannot answer questions","The AI can only generate images","The AI can inspect information but cannot directly change systems","The AI can delete files but not edit them"], correct:2, explain:"Read-only access allows analysis while reducing the risk of accidental changes.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-166", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should risky AI actions require confirmation?", options:["Confirmation makes the AI less useful in every case","Confirmation prevents logs from being created","Confirmation automatically fixes bad code","A human checkpoint can catch mistakes before damage occurs"], correct:3, explain:"Confirmation gates are useful before changes that are sensitive, destructive, or hard to reverse.", reward:"Approval Sense" },
  { id:"ai-automation-safety-167", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe rule for AI-generated shell commands?", options:["Read and understand the command before running it","Run commands faster if they are long","Ignore flags and parameters if the AI explains them","Run destructive commands first to save time"], correct:0, explain:"Commands can change or delete data, so they must be understood before execution.", reward:"Command Caution" },
  { id:"ai-automation-safety-168", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why is copying secrets into AI prompts risky?", options:["Secrets become easier to rotate automatically","The secret may be stored, logged, or exposed outside intended controls","Secrets cannot be processed by language models","Secrets stop the AI from answering"], correct:1, explain:"Secrets should not be placed in tools or locations that are not approved for secret handling.", reward:"Secret Safety" },
  { id:"ai-automation-safety-169", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What should you do if an AI tool accidentally sees a secret?", options:["Post the secret again with more context","Assume exposure is impossible","Rotate or revoke the secret according to procedure","Ignore it if the AI did not mention it"], correct:2, explain:"Exposed secrets should be treated as potentially compromised and rotated or revoked.", reward:"Secret Safety" },
  { id:"ai-automation-safety-170", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated configuration changes be reviewed carefully?", options:["Configuration has no security impact","Reviewing config prevents all outages","Only source code can contain mistakes","Config changes can weaken security, break systems, or expose data"], correct:3, explain:"Configuration controls behavior, access, and security, so generated changes need review.", reward:"Config Review" },
  { id:"ai-automation-safety-171", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe attitude toward AI speed?", options:["Speed is useful, but validation and supervision still matter","Faster output always means better quality","Speed removes the need for scope control","Fast tools should bypass review"], correct:0, explain:"AI speed is valuable only when paired with quality control.", reward:"Quality Mindset" },
  { id:"ai-automation-safety-172", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why can AI-generated content still need human editing?", options:["AI cannot produce any useful text","Generated content may miss tone, context, accuracy, or quality goals","Human editing prevents all spelling mistakes only","Generated content is always too short"], correct:1, explain:"Humans define the standard and verify whether output fits the purpose.", reward:"Human Review" },
  { id:"ai-automation-safety-173", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What does 'automation at scale' mean?", options:["Automation that only affects one test file","Automation that cannot interact with systems","Automation that can repeat actions across many items or systems","Automation that runs only after manual typing"], correct:2, explain:"Automation can multiply both good actions and mistakes across many targets.", reward:"Automation Caution" },
  { id:"ai-automation-safety-174", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-assisted bulk changes be especially controlled?", options:["Bulk changes cannot be reviewed later","Bulk changes are always low risk","Bulk changes only affect comments","A mistake can affect many files, users, or systems at once"], correct:3, explain:"Bulk automation increases blast radius, so controls and validation are important.", reward:"Automation Caution" },
  { id:"ai-automation-safety-175", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is the purpose of an AI usage policy?", options:["To define approved tools, allowed data, review expectations, and accountability","To prevent all employees from using computers","To remove the need for security reviews","To make all AI output official"], correct:0, explain:"AI usage policy sets boundaries for safe and responsible use.", reward:"Policy Sense" },
  { id:"ai-automation-safety-176", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why is shadow AI difficult for security teams?", options:["Shadow AI always uses approved logging","Unapproved tools may handle sensitive data or actions without visibility","Unapproved AI tools cannot process business data","Security teams automatically see every prompt"], correct:1, explain:"Shadow AI bypasses normal review, logging, vendor risk, and data protection controls.", reward:"Shadow AI Awareness" },
  { id:"ai-automation-safety-177", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a good control for reducing shadow AI risk?", options:["Allow every tool without review","Ban documentation of AI usage","Provide approved AI tools and clear rules for safe use","Ask users to hide prompts from security teams"], correct:2, explain:"Approved tools and clear guidance reduce the pressure to use risky unsanctioned tools.", reward:"Policy Sense" },
  { id:"ai-automation-safety-178", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI tools be included in vendor risk review?", options:["AI vendors cannot store data","Vendor risk only applies to hardware","AI tools never change after purchase","AI tools may process sensitive data, logs, code, or business information"], correct:3, explain:"AI vendors may affect privacy, security, compliance, and data handling.", reward:"Vendor Risk" },
  { id:"ai-automation-safety-179", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What should be checked before sending logs to an AI tool?", options:["Whether the logs contain sensitive data and whether the tool is approved for that data","Whether the log text looks visually neat","Whether the AI prefers shorter filenames","Whether the user wants a faster answer"], correct:0, explain:"Logs may contain usernames, IPs, tokens, paths, or business-sensitive data.", reward:"Data Care" },
  { id:"ai-automation-safety-180", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI tools not silently train on sensitive company data unless approved?", options:["Training always deletes the original data","Sensitive data may be retained, reproduced, or exposed outside intended use","Training prevents all model mistakes","Company data cannot improve models"], correct:1, explain:"Training or retention settings must match company policy and legal requirements.", reward:"Data Care" },
  { id:"ai-automation-safety-181", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of AI plugins or connected tools?", options:["Plugins cannot interact with external systems","Plugins always run in read-only mode","They may give the AI access to data or actions beyond simple chat","Plugins prevent prompt injection"], correct:2, explain:"Connected tools expand what an AI can see and do, increasing risk.", reward:"Tool Control" },
  { id:"ai-automation-safety-182", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI tool permissions be reviewed periodically?", options:["Permissions never change after setup","Reviews disable all useful automation","Old or excessive permissions may remain after the original need is gone","Permission reviews prevent all hallucinations"], correct:2, explain:"Periodic review helps remove stale or overly broad access.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-183", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of letting an AI agent read web pages and then run commands?", options:["Untrusted page content may influence the agent into unsafe command execution","Web pages cannot contain instructions","Running commands after reading content is always safe","Command execution cannot affect local files"], correct:0, explain:"External content should not be allowed to directly control tool execution.", reward:"Injection Awareness" },
  { id:"ai-automation-safety-184", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should untrusted content be labeled or isolated in AI workflows?", options:["Labeling makes the content impossible to read","It helps the AI and system treat it as data, not as trusted instruction","Untrusted content is always harmless if short","Isolation removes the need for access control"], correct:1, explain:"Separating instructions from untrusted data helps resist prompt injection.", reward:"Prompt Guardrails" },
  { id:"ai-automation-safety-185", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a safer design for AI handling customer emails?", options:["Let the AI obey any instructions inside the email","Give the AI admin access to all customer records","Treat email text as untrusted data and restrict actions it can take","Disable all human review for faster processing"], correct:2, explain:"Customer emails can contain malicious or misleading instructions, so action limits matter.", reward:"Injection Awareness" },
  { id:"ai-automation-safety-186", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI output that affects customers be reviewed carefully?", options:["Customer-facing mistakes can create misinformation, privacy issues, or business harm","Customer-facing output cannot be wrong","Review prevents customers from seeing any messages","AI output is always legally approved"], correct:0, explain:"Public or customer-facing AI output can create direct business and trust impact.", reward:"Human Review" },
  { id:"ai-automation-safety-187", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of using AI to classify security alerts without validation?", options:["Alert classification cannot be automated at all","Misclassification may hide true positives or waste analyst time on false positives","Validation prevents alerts from being created","AI can only classify low-severity alerts"], correct:1, explain:"Classification must be measured and reviewed so important alerts are not missed.", reward:"SOC Assist" },
  { id:"ai-automation-safety-188", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-assisted alert closure require evidence?", options:["Evidence shows why the alert is safe to close or needs escalation","Evidence makes alert queues slower by design","AI closure decisions are always correct","Evidence should be deleted after closure"], correct:0, explain:"Closure decisions should be traceable to facts, not unsupported AI judgement.", reward:"Evidence First" },
  { id:"ai-automation-safety-189", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a good metric for AI-assisted SOC quality?", options:["Only the number of alerts closed per hour","Accuracy against reviewed cases, missed true positives, false positives, and analyst agreement","How confident the AI sounds","How long the AI response is"], correct:1, explain:"Quality should be measured with outcomes, not just speed or confidence.", reward:"Quality Metrics" },
  { id:"ai-automation-safety-190", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why can focusing only on AI productivity be risky?", options:["Speed without review can increase hidden errors, weak decisions, or unsafe changes","Productivity cannot improve with AI","Review is never needed when output is fast","Faster work always means lower risk"], correct:0, explain:"AI productivity must be balanced with oversight and quality controls.", reward:"Quality Mindset" },
  { id:"ai-automation-safety-191", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated playbooks be tested with examples?", options:["A playbook that sounds good may still fail on real cases or edge conditions","Playbooks cannot contain mistakes","Testing makes playbooks unusable","Examples remove all need for analyst judgment"], correct:0, explain:"Examples reveal whether the playbook works in realistic situations.", reward:"Playbook Validation" },
  { id:"ai-automation-safety-192", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a safe way to use AI for detection-rule writing?", options:["Generate logic, then validate it with known-good and known-bad events","Deploy generated rules without review","Ignore false positives during testing","Let the AI remove all old detections"], correct:0, explain:"Detection rules need test data and review before production use.", reward:"Detection Validation" },
  { id:"ai-automation-safety-193", tier:"Advanced", topic:"AI & Automation Safety", prompt:"An AI agent can read source code, access secrets, and open outbound network connections. What is the main concern?", options:["It has a high-risk combination of sensitive data access and possible exfiltration paths","Source code is never sensitive","Outbound network access prevents data leakage","Secret access makes the agent safer"], correct:0, explain:"Combining secrets with outbound tools increases the need for strict controls and monitoring.", reward:"Data Leakage" },
  { id:"ai-automation-safety-194", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why is AI-generated code especially risky in authentication or authorization logic?", options:["Auth code cannot contain bugs","Small mistakes can create access bypasses, privilege issues, or data exposure","Auth code is never security-sensitive","AI refuses to generate auth-related code"], correct:1, explain:"Authentication and authorization errors can directly affect who gets access.", reward:"AI Code Review" },
  { id:"ai-automation-safety-195", tier:"Advanced", topic:"AI & Automation Safety", prompt:"What should be reviewed when AI modifies infrastructure-as-code?", options:["Only whether the comments are formatted nicely","Resource exposure, permissions, network rules, secrets, and environment impact","Only whether the file name changed","Whether the AI used friendly wording"], correct:1, explain:"Infrastructure changes can expose services, grant access, or alter security boundaries.", reward:"Config Review" },
  { id:"ai-automation-safety-196", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why is rollback planning not enough by itself for AI automation?", options:["Rollback cannot help after any mistake","Rollback must be paired with prevention, validation, logging, and approval controls","Rollback makes testing unnecessary","Rollback guarantees no data exposure happened"], correct:1, explain:"Rollback helps recovery, but it does not replace safeguards that prevent or detect harm.", reward:"Rollback Sense" },
  { id:"ai-automation-safety-197", tier:"Advanced", topic:"AI & Automation Safety", prompt:"A model recommends disabling a detection because it creates noise. What should happen first?", options:["Review evidence, false-positive rate, true-positive value, and possible tuning alternatives","Disable it immediately to reduce dashboard noise","Delete the detection history to avoid confusion","Assume the model understands the environment perfectly"], correct:0, explain:"Detection changes should be evidence-based and consider both noise and missed-threat risk.", reward:"Detection Validation" },
  { id:"ai-automation-safety-198", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why is AI-assisted remediation risky in identity systems?", options:["Identity systems cannot be changed by automation","Mistakes can lock out users, weaken access controls, or grant the wrong permissions","Identity remediation never affects business operations","AI cannot generate identity-related actions"], correct:1, explain:"Identity changes can have broad access and business impact, so controls are necessary.", reward:"Approval Sense" },
  { id:"ai-automation-safety-199", tier:"Advanced", topic:"AI & Automation Safety", prompt:"What is a strong control for AI agents that can take external actions?", options:["Allow actions only through approved tools, with scoped permissions, logs, and approval gates","Let the agent create new tools when blocked","Disable all monitoring for privacy","Treat all external content as trusted instructions"], correct:0, explain:"External action capability needs strict boundaries, logging, and human checkpoints.", reward:"Tool Control" },
  { id:"ai-automation-safety-200", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should AI governance include incident response planning?", options:["AI incidents can involve data leakage, unsafe actions, bad outputs, or tool misuse that need response","AI governance prevents every incident automatically","Incident response is only for malware cases","AI tools cannot create security events"], correct:0, explain:"Organizations need plans for investigating and containing AI-related failures or misuse.", reward:"AI Incident Response" },
  { id:"ai-automation-safety-201", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated code be reviewed even if it passes syntax checks?", options:["Syntax can be valid while logic, security, or requirements are still wrong","Syntax checks prove security quality","Valid syntax means the code meets business needs","Syntax checks detect all privacy issues"], correct:0, explain:"Code can run or parse correctly while still being unsafe or incorrect.", reward:"AI Code Review" },
  { id:"ai-automation-safety-202", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe response if AI suggests removing error handling?", options:["Remove it to make the code shorter","Ask why it is safe and verify the impact before accepting","Remove all logs as well","Assume the AI found unnecessary code"], correct:1, explain:"Error handling often protects reliability and visibility, so removals need review.", reward:"AI Code Review" },
  { id:"ai-automation-safety-203", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated changes be checked against user requirements?", options:["Requirements are only useful before coding starts","AI always knows what users want","The change may work technically but fail the actual goal","Checking requirements prevents all syntax errors"], correct:2, explain:"A feature can function and still be wrong for the intended use case.", reward:"Requirement Check" },
  { id:"ai-automation-safety-204", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI not silently add new features?", options:["New features always improve the project","Silent features reduce testing needs","Features do not affect project scope","Unrequested features can increase complexity, bugs, and review burden"], correct:3, explain:"Scope control keeps AI work focused and manageable.", reward:"Scope Control" },
  { id:"ai-automation-safety-205", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated documentation be checked?", options:["It may describe features, risks, or behavior incorrectly","Documentation cannot contain mistakes","AI-written documentation is always complete","Checking documentation breaks formatting"], correct:0, explain:"Documentation guides users and maintainers, so accuracy matters.", reward:"Documentation Assist" },
  { id:"ai-automation-safety-206", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to use AI for writing commit messages?", options:["Let AI hide risky changes","Use AI to draft, then confirm the message matches the actual diff","Write only 'update' for every commit","Skip commit messages for AI work"], correct:1, explain:"Commit messages should accurately describe what changed and why.", reward:"Version Control" },
  { id:"ai-automation-safety-207", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated diffs be reviewed before merge?", options:["Diffs are only for decoration","AI-generated diffs cannot contain bugs","Diff review shows exactly what changed and whether it matches intent","Diff review removes the need for testing"], correct:2, explain:"Diff review helps catch unwanted or risky changes.", reward:"Diff Review" },
  { id:"ai-automation-safety-208", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe rule for AI-generated file deletion commands?", options:["Run them immediately if the AI is confident","Use the broadest wildcard possible","Delete first and review after","Confirm the target path and purpose before running"], correct:3, explain:"Deletion commands can cause permanent loss if paths or patterns are wrong.", reward:"Command Caution" },
  { id:"ai-automation-safety-209", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated security settings be tested?", options:["They can accidentally weaken protection, block users, or break functionality","Security settings cannot affect users","Testing makes security settings useless","AI-generated settings are always correct"], correct:0, explain:"Security settings need validation because they affect real behavior.", reward:"Config Review" },
  { id:"ai-automation-safety-210", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What should happen if AI output includes a secret?", options:["Leave it in place if it is only in a test file","Treat it as sensitive and rotate or remove it according to procedure","Post it into another AI tool for checking","Ignore it unless the app fails"], correct:1, explain:"Secrets exposed in output should be handled as potential leaks.", reward:"Secret Safety" },
  { id:"ai-automation-safety-211", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated examples avoid real customer data?", options:["Customer data cannot be used in examples","Examples never leave local machines","Real customer data may create privacy and exposure risk","Customer data makes examples too short"], correct:2, explain:"Synthetic or sanitized examples reduce privacy risk.", reward:"Data Care" },
  { id:"ai-automation-safety-212", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe practice before giving AI access to project files?", options:["Give it the entire disk by default","Disable version control first","Hide the project goals","Define which files it may read or edit"], correct:3, explain:"File access should match the task and scope.", reward:"Tool Control" },
  { id:"ai-automation-safety-213", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated test results be verified?", options:["The AI may misread failures or claim success without evidence","Test results are always fake","Verification prevents the need for tests","AI cannot summarize test output"], correct:0, explain:"Claims about tests should match actual test output.", reward:"Validation Loop" },
  { id:"ai-automation-safety-214", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe use of AI for learning?", options:["Memorize answers without understanding","Ask for explanations, then practice applying the concept","Skip labs because AI can explain everything","Trust every generated answer as final"], correct:1, explain:"AI can support learning, but practice and verification build skill.", reward:"Learning Assist" },
  { id:"ai-automation-safety-215", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should generated quiz options be similar in style?", options:["Different styles make the correct answer impossible","Style does not affect learning","Uneven options can make the correct answer obvious without knowledge","All options should be identical"], correct:2, explain:"Good options test understanding rather than visual guessing.", reward:"Content Quality" },
  { id:"ai-automation-safety-216", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe response if AI output is too vague?", options:["Use it anyway","Assume vagueness means flexibility","Delete the prompt history","Ask for specifics, examples, or evidence"], correct:3, explain:"Vague output should be clarified before it drives action.", reward:"Verify Output" },
  { id:"ai-automation-safety-217", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-assisted workflows keep humans responsible?", options:["Humans decide where AI is used and whether outputs are accepted","AI tools can take legal responsibility by themselves","Responsibility disappears when automation starts","Human review prevents all mistakes"], correct:0, explain:"AI can assist, but humans remain accountable for decisions and outcomes.", reward:"Accountability" },
  { id:"ai-automation-safety-218", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to handle AI-generated risk ratings?", options:["Accept the rating without evidence","Compare the rating with evidence, context, and policy","Use only the highest rating every time","Delete low-rated alerts automatically"], correct:1, explain:"Risk ratings should be grounded in evidence and context.", reward:"Evidence First" },
  { id:"ai-automation-safety-219", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated scripts avoid hidden behavior?", options:["Hidden behavior makes scripts faster","Hidden behavior prevents logs","Reviewers need to understand what the script will do","Hidden behavior improves security"], correct:2, explain:"Transparent scripts are easier to review and safer to run.", reward:"Command Caution" },
  { id:"ai-automation-safety-220", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What should be done before AI automation sends messages to users?", options:["Disable approvals","Use the first draft immediately","Remove evidence links","Review content, audience, timing, and possible impact"], correct:3, explain:"User-facing automation can cause confusion or harm if wrong.", reward:"Human Review" },
  { id:"ai-automation-safety-221", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated answers include uncertainty when needed?", options:["Uncertainty helps prevent guesses from being treated as facts","Uncertainty always means the answer is useless","Uncertainty should be hidden from reports","Uncertainty prevents review"], correct:0, explain:"Clear uncertainty helps reviewers know what still needs checking.", reward:"Evidence First" },
  { id:"ai-automation-safety-222", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to use AI for brainstorming?", options:["Treat every idea as approved work","Use ideas as options, then select based on goals and constraints","Add every suggestion to production","Ignore project priorities"], correct:1, explain:"Brainstorming creates possibilities, not final decisions.", reward:"Product Thinking" },
  { id:"ai-automation-safety-223", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated changes not bypass normal review because they are fast?", options:["Fast output is always safer","Review slows all projects permanently","Speed does not guarantee correctness, security, or fit","AI-generated code cannot be reviewed"], correct:2, explain:"Fast generation still needs quality control.", reward:"Quality Mindset" },
  { id:"ai-automation-safety-224", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe rule when AI suggests changing permissions?", options:["Accept broader permissions to avoid errors","Ignore who gets access","Disable audit logs after the change","Verify the minimum needed access and approval reason"], correct:3, explain:"Permission changes can create security risk and need careful review.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-225", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-assisted work have clear success criteria?", options:["Clear criteria make it possible to judge whether the output is actually good","Success criteria prevent all bugs","Criteria are only needed after release","AI ignores success criteria completely"], correct:0, explain:"Without criteria, the AI may produce output that looks useful but misses the goal.", reward:"Requirement Check" },
  { id:"ai-automation-safety-226", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why is AI-generated authentication code high risk?", options:["Authentication code cannot contain logic errors","Authentication controls who can access the system, so mistakes can expose accounts","AI refuses to generate authentication code","Authentication code only affects visual design"], correct:1, explain:"Authentication mistakes can directly affect account security.", reward:"AI Code Review" },
  { id:"ai-automation-safety-227", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What should reviewers check in AI-generated authorization logic?", options:["Only whether the code is short","Only whether comments are friendly","Roles, permissions, denied cases, allowed cases, and edge cases","Only whether the page loads"], correct:2, explain:"Authorization review must confirm users only get intended access.", reward:"Access Control" },
  { id:"ai-automation-safety-228", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why is AI-generated logging code sensitive?", options:["Logs cannot contain useful evidence","Logging has no security impact","Logs are always encrypted automatically","It may expose secrets, personal data, or internal details"], correct:3, explain:"Logs should be useful without leaking sensitive information.", reward:"Data Care" },
  { id:"ai-automation-safety-229", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a safe review step for AI-generated API calls?", options:["Check destination, data sent, authentication, error handling, and approval","Allow all endpoints by default","Ignore what data leaves the system","Disable network logging"], correct:0, explain:"API calls can move data or trigger actions, so they need review.", reward:"Tool Control" },
  { id:"ai-automation-safety-230", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why are AI-generated dependencies a supply-chain concern?", options:["Dependencies cannot contain vulnerabilities","New packages may introduce vulnerabilities, license issues, or untrusted code","Dependencies always reduce risk","Package names prove trustworthiness"], correct:1, explain:"Dependencies should be checked before adding them.", reward:"Dependency Review" },
  { id:"ai-automation-safety-231", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of hallucinated package names?", options:["They make code compile faster","They prevent dependency confusion","Attackers may publish similar packages to catch users who trust the hallucination","They always point to official libraries"], correct:2, explain:"Hallucinated packages can create an opening for supply-chain abuse.", reward:"Dependency Review" },
  { id:"ai-automation-safety-232", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated infrastructure changes be reviewed?", options:["Infrastructure files cannot affect live systems","AI cannot edit infrastructure code","Infrastructure code is only documentation","They may expose services, weaken network rules, or create costly resources"], correct:3, explain:"Infrastructure-as-code can change real resources and security boundaries.", reward:"Config Review" },
  { id:"ai-automation-safety-233", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a useful control for AI-generated remediation?", options:["Dry-run output, approval, logging, rollback, and scoped permissions","No logs, no approval, and full access","Immediate production execution","Removing all human checkpoints"], correct:0, explain:"Remediation can cause damage, so safeguards matter.", reward:"Automation Caution" },
  { id:"ai-automation-safety-234", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated detections include false-positive testing?", options:["False positives do not matter","Testing benign examples helps avoid noisy or misleading alerts","False-positive testing disables detection logic","Only malicious examples are useful"], correct:1, explain:"Good detections should catch threats without overwhelming analysts.", reward:"Detection Validation" },
  { id:"ai-automation-safety-235", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What should AI-generated detection logic include?", options:["Only a catchy rule name","Only one exact filename","Required data source, logic, fields, assumptions, and test cases","No explanation to avoid bias"], correct:2, explain:"Detection logic should be understandable and testable.", reward:"Detection Validation" },
  { id:"ai-automation-safety-236", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated KQL, SPL, or SQL be reviewed?", options:["Search queries cannot be wrong","Search language is always safe","Review makes queries impossible to run","Wrong logic can miss events, overmatch, cost too much, or expose data"], correct:3, explain:"Search queries need review for correctness, performance, and data handling.", reward:"Query Review" },
  { id:"ai-automation-safety-237", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of letting AI auto-close alerts?", options:["It may close true positives if classification is wrong","It makes every alert more accurate","It prevents all analyst fatigue","It creates perfect evidence automatically"], correct:0, explain:"Alert closure should be evidence-based and reviewable.", reward:"SOC Assist" },
  { id:"ai-automation-safety-238", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-assisted SOC summaries preserve raw evidence?", options:["Raw evidence is only decoration","Analysts need source data to verify conclusions","Raw evidence prevents all false positives","Summaries cannot contain errors"], correct:1, explain:"Source evidence lets analysts confirm or challenge the summary.", reward:"Evidence First" },
  { id:"ai-automation-safety-239", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a good quality metric for AI-generated detections?", options:["Only how many rules were generated","Only whether the rule name sounds professional","True positives, false positives, coverage, test results, and analyst feedback","How many words the explanation uses"], correct:2, explain:"Detection quality depends on performance and usefulness, not volume.", reward:"Quality Metrics" },
  { id:"ai-automation-safety-240", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated playbooks include escalation points?", options:["Escalation points make playbooks longer only","Escalation prevents all incidents","Escalation should happen randomly","They show when human expertise or authority is needed"], correct:3, explain:"Escalation criteria help risky cases reach the right people.", reward:"Playbook Validation" },
  { id:"ai-automation-safety-241", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why is indirect prompt injection dangerous?", options:["Malicious instructions can hide inside content the AI reads","It only affects image generation","It cannot affect agents with tools","It always requires admin passwords"], correct:0, explain:"Untrusted content can try to manipulate AI behavior.", reward:"Injection Awareness" },
  { id:"ai-automation-safety-242", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a safe design for AI reading emails or tickets?", options:["Let it obey all text inside the message","Treat message content as untrusted data and limit actions","Give it permission to change all accounts","Disable logging for privacy"], correct:1, explain:"Emails and tickets may contain malicious or misleading instructions.", reward:"Prompt Guardrails" },
  { id:"ai-automation-safety-243", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should connected AI tools be monitored?", options:["Monitoring prevents all AI mistakes","Connected tools cannot cause harm","They may access data or perform actions, so their use should be visible","Monitoring makes permissions unnecessary"], correct:2, explain:"Tool-connected AI can affect systems and needs oversight.", reward:"Tool Control" },
  { id:"ai-automation-safety-244", tier:"Advanced", topic:"AI & Automation Safety", prompt:"An AI agent has read access to secrets and write access to tickets. What risk remains?", options:["Secrets cannot appear in generated text","Ticket writing prevents data leakage","Read access is always harmless","Secrets could be exposed through ticket content, logs, or summaries"], correct:3, explain:"Sensitive data can leak through indirect output channels.", reward:"Data Leakage" },
  { id:"ai-automation-safety-245", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should tool-using AI agents separate read, write, and execute permissions?", options:["Different capabilities have different risk and should be controlled separately","All tool permissions are equal","Execute permission is always safer than read-only","Permission separation prevents all hallucinations"], correct:0, explain:"Granular permissions reduce unnecessary blast radius.", reward:"Tool Control" },
  { id:"ai-automation-safety-246", tier:"Advanced", topic:"AI & Automation Safety", prompt:"What is a risk of AI-generated IAM policy changes?", options:["IAM policies cannot affect real access","Valid syntax can still grant excessive or unintended permissions","IAM policies are only visual labels","AI cannot generate IAM text"], correct:1, explain:"Permission logic must be reviewed beyond syntax.", reward:"Approval Sense" },
  { id:"ai-automation-safety-247", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should AI-generated architecture advice be challenged?", options:["Architecture advice can never be useful","AI cannot discuss architecture","It may add unnecessary complexity or ignore constraints","Architecture decisions have no maintenance cost"], correct:2, explain:"Architecture must match real needs, not just sound impressive.", reward:"Product Thinking" },
  { id:"ai-automation-safety-248", tier:"Advanced", topic:"AI & Automation Safety", prompt:"A model recommends removing a noisy detection. What should defenders check first?", options:["Only whether the dashboard becomes cleaner","Only whether the model sounds confident","Whether the rule has a short name","False positives, true positives, coverage, alternatives, and tuning options"], correct:3, explain:"Detection changes should balance noise reduction with threat coverage.", reward:"Detection Validation" },
  { id:"ai-automation-safety-249", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should autonomous remediation have kill-switch controls?", options:["Automation may need to be stopped quickly if it behaves incorrectly","Kill switches prevent all bugs before execution","Kill switches replace logging","Automation should never be interrupted"], correct:0, explain:"Emergency stop controls reduce damage when automation goes wrong.", reward:"Automation Caution" },
  { id:"ai-automation-safety-250", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why is AI governance connected to security culture?", options:["Security culture has no effect on AI use","Governance is only a technical setting","AI governance defines how people balance speed, oversight, responsibility, and acceptable risk","AI tools remove the need for human responsibility"], correct:2, explain:"Governance works only when people understand and follow responsible AI practices.", reward:"Governance Sense" },
  { id:"ai-automation-safety-251", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated commands that delete or overwrite files require extra care?", options:["They can cause data loss if the command, path, or target is wrong","They are always harmless if generated by an AI tool","They cannot affect files without a backend server","They automatically create backups before running"], correct:0, explain:"Destructive commands should be reviewed carefully because mistakes can remove or overwrite important data.", reward:"Command Caution" },
  { id:"ai-automation-safety-252", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe response if an AI tool suggests changing many files unexpectedly?", options:["Commit the changes quickly before reviewing them","Stop and inspect the diff before continuing","Assume broad changes mean the AI understood better","Delete the project snapshot to reduce confusion"], correct:1, explain:"Unexpected broad changes should be reviewed before more work continues.", reward:"Diff Review" },
  { id:"ai-automation-safety-253", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should project snapshots include current guardrails?", options:["Snapshots make version control unnecessary","Guardrails prevent all syntax errors automatically","Guardrails help future sessions preserve scope and avoid repeated mistakes","Future sessions cannot read written instructions"], correct:2, explain:"Snapshots help carry important rules and decisions into later AI sessions.", reward:"Context Management" },
  { id:"ai-automation-safety-254", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a useful check after AI edits a question bank?", options:["Only confirm that the file size became larger","Skip validation if the AI says it is complete","Commit immediately because text files cannot break code","Check IDs, counts, tiers, answer balance, duplicates, and question quality"], correct:3, explain:"Question banks need both structural checks and content-quality review.", reward:"Content Quality" },
  { id:"ai-automation-safety-255", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated code not be judged only by whether it runs once?", options:["A single run may miss edge cases, regressions, security issues, or bad design","Running once proves the code is production-ready","If it opens in a browser, no review is needed","Working output means requirements were fully met"], correct:0, explain:"Functionality is only one part of quality; review and validation still matter.", reward:"Quality Mindset" },
  { id:"ai-automation-safety-256", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a good use of AI during code review?", options:["Approve the pull request without reading it","Help explain risky changes while the human still checks the diff","Remove comments that mention uncertainty","Hide test failures from the reviewer"], correct:1, explain:"AI can assist review, but humans should still verify changes and risk.", reward:"AI Code Review" },
  { id:"ai-automation-safety-257", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why is an AI-generated explanation not enough proof that a change is safe?", options:["Explanations cannot describe code at all","Safe changes never need explanations","Explanations can be incomplete or wrong, while tests and diffs show evidence","Only long explanations can be trusted"], correct:2, explain:"Claims should be checked against actual changes, tests, and behavior.", reward:"Evidence First" },
  { id:"ai-automation-safety-258", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What does 'blast radius' mean in AI automation?", options:["How colorful the AI interface looks during a task","How many prompts are needed to finish a change","The amount of memory used by the model","How much damage or impact a mistake could cause"], correct:3, explain:"Blast radius describes how widely an error could affect files, users, systems, or data.", reward:"Automation Caution" },
  { id:"ai-automation-safety-259", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI tools be given test data instead of real sensitive data when possible?", options:["Test data reduces privacy and exposure risk during experimentation","Test data prevents all model hallucinations","Real data cannot be processed by AI tools","Sensitive data is never useful for testing"], correct:0, explain:"Using safe test data lowers risk while still allowing workflow validation.", reward:"Data Care" },
  { id:"ai-automation-safety-260", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is data minimization in AI use?", options:["Giving the AI every file in the project by default","Sharing only the data needed for the task","Removing all context so the AI guesses freely","Using the shortest prompt possible"], correct:1, explain:"Data minimization limits exposure by sharing only what is necessary.", reward:"Data Care" },
  { id:"ai-automation-safety-261", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI tools avoid retaining sensitive prompts unless approved?", options:["Retained prompts always improve security","Prompt retention prevents data leakage","Prompt retention may create future exposure, privacy, or compliance risk","Sensitive prompts cannot contain business data"], correct:2, explain:"Retention settings matter because prompts may include sensitive information.", reward:"Data Care" },
  { id:"ai-automation-safety-262", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe habit when pasting logs into AI tools?", options:["Paste all raw logs without checking them","Remove timestamps from every log line","Use only logs from production incidents","Check for secrets, tokens, personal data, and sensitive system details first"], correct:3, explain:"Logs can contain sensitive values and should be reviewed or redacted before sharing.", reward:"Data Care" },
  { id:"ai-automation-safety-263", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated scripts be reviewed before execution?", options:["Scripts may change files, permissions, services, or network settings","Scripts cannot affect systems unless compiled","Reviewing scripts prevents all syntax errors","AI-generated scripts are always read-only"], correct:0, explain:"Scripts can perform real actions, so their commands and targets should be understood.", reward:"Command Caution" },
  { id:"ai-automation-safety-264", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safer approach to AI-generated automation?", options:["Run it against production first to save time","Start with a dry run or simulation before allowing real changes","Disable output logs to reduce noise","Let the automation decide its own permissions"], correct:1, explain:"Dry runs help reveal what automation would do before it changes real systems.", reward:"Automation Caution" },
  { id:"ai-automation-safety-265", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why is a dry-run mode useful?", options:["It hides mistakes from reviewers","It removes the need for approval","It shows likely actions without applying real changes","It makes risky actions irreversible"], correct:2, explain:"Dry-run mode supports safer review before execution.", reward:"Automation Caution" },
  { id:"ai-automation-safety-266", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What should happen when AI output affects security policy?", options:["It should bypass normal change control","It should be hidden from audit logs","It should be applied to all users immediately","It should be reviewed and approved by responsible humans before use"], correct:3, explain:"Security-policy changes need clear ownership, review, and approval.", reward:"Approval Sense" },
  { id:"ai-automation-safety-267", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated recommendations include assumptions?", options:["Assumptions help readers see what the recommendation depends on","Assumptions make recommendations legally perfect","Assumptions remove the need for evidence","Assumptions should always be hidden"], correct:0, explain:"Stating assumptions makes uncertainty visible and reviewable.", reward:"Evidence First" },
  { id:"ai-automation-safety-268", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to use AI for prioritizing tasks?", options:["Let AI choose priorities without business context","Use AI suggestions as input, then compare them with risk, value, and constraints","Always do the task the AI lists first","Ignore human goals if the AI gives a plan"], correct:1, explain:"AI can help sort ideas, but priorities should match real goals and constraints.", reward:"Product Thinking" },
  { id:"ai-automation-safety-269", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated roadmaps be reviewed for scope creep?", options:["Roadmaps cannot contain too many features","Scope creep always improves user experience","AI may add attractive but unnecessary features that distract from the core goal","Reviewing roadmaps prevents all technical debt"], correct:2, explain:"AI may expand the project beyond what is useful or manageable.", reward:"Scope Control" },
  { id:"ai-automation-safety-270", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a good question before accepting an AI-suggested feature?", options:["Can this make the project bigger immediately?","Did the AI use confident language?","Can we avoid testing it?","Does this support the current goal and priority list?"], correct:3, explain:"Features should be judged by purpose and priority, not novelty alone.", reward:"Product Thinking" },
  { id:"ai-automation-safety-271", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated learning content avoid joke distractors?", options:["Joke distractors make the correct answer guessable without understanding","Joke distractors always improve retention","Joke distractors prevent duplicate questions","Joke distractors are required for beginner topics"], correct:0, explain:"Good distractors should be plausible misunderstandings, not obviously silly answers.", reward:"Content Quality" },
  { id:"ai-automation-safety-272", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What makes a question useful for learning?", options:["The correct answer is always the longest option","It rewards understanding the concept rather than spotting a visual clue","The wrong answers are unrelated to the topic","The explanation repeats the option without teaching"], correct:1, explain:"Useful questions test understanding and explain why the correct answer matters.", reward:"Content Quality" },
  { id:"ai-automation-safety-273", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should explanations be checked in generated question banks?", options:["Explanations are never shown to players","Explanations replace the need for correct answers","Explanations may be vague, wrong, or inconsistent with the correct answer","Long explanations always mean better learning"], correct:2, explain:"Explanations are part of learning quality and should match the question.", reward:"Content Quality" },
  { id:"ai-automation-safety-274", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a sign that answer options are poorly designed?", options:["All options are plausible and similar in style","The correct answer is only clear if the learner understands the concept","The explanation clarifies the concept","One option is serious while the others are unrelated or silly"], correct:3, explain:"Uneven options make questions easier to guess and less useful.", reward:"Content Quality" },
  { id:"ai-automation-safety-275", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI work be committed after clean checkpoints?", options:["It protects known-good progress before risky next steps","It removes the need to test the next task","It makes all future AI output correct","It hides mistakes from version history"], correct:0, explain:"Clean checkpoints make it easier to recover when later work goes sideways.", reward:"Version Control" },
  { id:"ai-automation-safety-276", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why is AI-generated code in input validation especially sensitive?", options:["Input validation never affects security","Input validation affects whether unsafe data can reach dangerous operations","AI cannot generate validation logic","Validation code only changes visual layout"], correct:1, explain:"Weak validation can lead to injection, bypass, or unsafe processing.", reward:"AI Code Review" },
  { id:"ai-automation-safety-277", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What should be reviewed if AI changes authentication flow code?", options:["Only whether the login page still has the same color","Only the file name of the login component","Credential handling, session logic, MFA behavior, redirects, and failure cases","Whether the AI wrote a long explanation"], correct:2, explain:"Authentication logic is security-critical and needs careful review.", reward:"AI Code Review" },
  { id:"ai-automation-safety-278", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why is AI-generated authorization logic high risk?", options:["Authorization code cannot contain bugs","AI tools refuse to edit authorization checks","Authorization only affects text labels","Authorization decides what users can access or do"], correct:3, explain:"Small authorization mistakes can expose data or grant excessive access.", reward:"AI Code Review" },
  { id:"ai-automation-safety-279", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What should be tested when AI changes authorization checks?", options:["Allowed and denied cases for different roles, users, and resources","Only whether the app loads","Only the fastest user path","Whether button colors changed"], correct:0, explain:"Authorization tests should verify both access granted and access denied cases.", reward:"Detection Validation" },
  { id:"ai-automation-safety-280", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated SQL or query logic be checked carefully?", options:["Queries cannot affect data","Queries may expose too much data, miss filters, or introduce injection risk","AI-generated queries are always optimized","Query logic never affects access control"], correct:1, explain:"Query logic can affect security, privacy, and correctness.", reward:"AI Code Review" },
  { id:"ai-automation-safety-281", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of AI-generated regular expressions in security tooling?", options:["Regular expressions cannot be generated by AI","Regex rules always detect exactly what was intended","They may be too broad, too narrow, or cause performance problems","Regex has no effect on security tools"], correct:2, explain:"Regex logic should be tested against matching and non-matching examples.", reward:"Detection Validation" },
  { id:"ai-automation-safety-282", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated detection rules include test cases?", options:["Test cases prove the detection name is catchy","Tests prevent attackers from changing tactics","Rules without tests cannot be saved","They help verify true-positive and false-positive behavior"], correct:3, explain:"Test cases show whether detection logic catches intended behavior without overmatching.", reward:"Detection Validation" },
  { id:"ai-automation-safety-283", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a useful false-positive check for AI-generated detections?", options:["Run the rule against normal activity examples that should not alert","Only run the rule against one known-bad event","Assume all matches are malicious","Remove fields that explain why an alert fired"], correct:0, explain:"False-positive checks reduce noisy detections and improve trust.", reward:"Detection Validation" },
  { id:"ai-automation-safety-284", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated KQL, SPL, or SQL be reviewed before use?", options:["Search queries cannot produce false positives","Search logic may be wrong, costly, or misleading even if syntax looks valid","All generated queries run efficiently by default","Generated searches cannot expose data"], correct:1, explain:"Search logic should be checked for correctness, cost, and data exposure.", reward:"Query Review" },
  { id:"ai-automation-safety-285", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of AI tools generating broad log searches?", options:["Broad searches always find only malicious activity","Large searches cannot affect performance","They may scan excessive data, create cost, or return misleading noise","Search volume is unrelated to cost"], correct:2, explain:"Broad searches can waste resources and produce confusing results.", reward:"Query Review" },
  { id:"ai-automation-safety-286", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What should be checked before using an AI-generated remediation script?", options:["Only whether the script has comments","Whether the AI response was short","Whether the filename sounds safe","Inputs, targets, permissions, dry-run output, rollback, and business impact"], correct:3, explain:"Remediation scripts can cause harm if targets or assumptions are wrong.", reward:"Approval Sense" },
  { id:"ai-automation-safety-287", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why is allowing AI to auto-merge code risky?", options:["It may bypass human review, tests, and understanding of security impact","Auto-merge prevents all broken builds","Only AI-generated code can be merged safely","Auto-merge always improves accountability"], correct:0, explain:"Merging code should require validation and review, especially for sensitive changes.", reward:"Review Burden" },
  { id:"ai-automation-safety-288", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a safer pattern for AI-generated pull requests?", options:["Large rewrites with no explanation","Small scoped changes, clear description, tests, and human review before merge","Skipping tests if the AI says it works","Merging immediately to avoid context loss"], correct:1, explain:"Small and well-documented changes are easier to review safely.", reward:"Diff Review" },
  { id:"ai-automation-safety-289", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated documentation mention limitations?", options:["Limitations make documents useless","Limitations should be hidden to sound confident","Limitations help users understand where the guidance may not apply","Documentation cannot include uncertainty"], correct:2, explain:"Limitations prevent overconfidence and misuse of guidance.", reward:"Documentation Assist" },
  { id:"ai-automation-safety-290", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of AI-generated architecture advice?", options:["Architecture advice cannot affect implementation","AI never suggests unnecessary services","Architecture diagrams are always accurate","It may optimize for sounding impressive instead of matching constraints and maintainability"], correct:3, explain:"Architecture should match real requirements, not just attractive patterns.", reward:"Product Thinking" },
  { id:"ai-automation-safety-291", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI not introduce external APIs without approval?", options:["External APIs can create data exposure, reliability, cost, and dependency risks","External APIs are always free and private","External APIs cannot fail","API use never changes project scope"], correct:0, explain:"External services add operational and security responsibilities.", reward:"Scope Control" },
  { id:"ai-automation-safety-292", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a useful question before giving AI access to a tool?", options:["Can the AI have admin access by default?","What is the minimum permission needed and what could go wrong?","Can logs be disabled for speed?","Can the AI decide its own scope?"], correct:1, explain:"Tool access should be scoped to need and risk.", reward:"Tool Control" },
  { id:"ai-automation-safety-293", tier:"Advanced", topic:"AI & Automation Safety", prompt:"An AI agent can edit code and run terminal commands. What control reduces risk most?", options:["Give it direct production access","Disable command output capture","Limit permissions, require review for risky commands, log actions, and use a safe branch","Let it change scope whenever blocked"], correct:2, explain:"Strong controls reduce the chance that tool-using agents cause hidden damage.", reward:"Tool Control" },
  { id:"ai-automation-safety-294", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why is prompt injection especially serious for agents with write access?", options:["Prompt injection cannot affect agents with tools","Write access prevents data exposure","Agents with write access always ignore untrusted content","Write access lets manipulated instructions cause real changes, not just bad text"], correct:3, explain:"When agents can write or execute, prompt injection can become an action risk.", reward:"Injection Awareness" },
  { id:"ai-automation-safety-295", tier:"Advanced", topic:"AI & Automation Safety", prompt:"A generated detection catches the sample event but also alerts on normal admin work. What is the likely issue?", options:["The rule may lack context or exclusions, causing false positives","Any alert on admin work proves compromise","The rule should be deployed without changes","False positives are not relevant to detection quality"], correct:0, explain:"Detection quality requires catching threats while limiting expected benign matches.", reward:"Detection Validation" },
  { id:"ai-automation-safety-296", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should AI-assisted SOC summaries preserve raw evidence links?", options:["Evidence links are only decorative","Raw evidence lets analysts verify claims and correct mistakes","Summaries replace all logs permanently","Raw evidence prevents escalation"], correct:1, explain:"Evidence-backed summaries are more trustworthy and reviewable.", reward:"Evidence First" },
  { id:"ai-automation-safety-297", tier:"Advanced", topic:"AI & Automation Safety", prompt:"What is a risk of letting AI tune detections only for fewer alerts?", options:["Fewer alerts always means better security","Detection tuning cannot create blind spots","It may reduce noise by suppressing real threat coverage","AI tuning never affects rule behavior"], correct:2, explain:"Tuning should reduce noise without hiding important attack behavior.", reward:"Detection Validation" },
  { id:"ai-automation-safety-298", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should AI usage be included in change-management records?", options:["AI usage removes the need for change records","Change records should hide tool involvement","AI-generated changes cannot affect production","AI involvement can affect review expectations, ownership, and traceability"], correct:3, explain:"Tracking AI-assisted changes supports accountability and later review.", reward:"Accountability" },
  { id:"ai-automation-safety-299", tier:"Advanced", topic:"AI & Automation Safety", prompt:"A team relies on AI to generate code but has no tests or review process. What is the main weakness?", options:["There is no reliable way to catch wrong, insecure, or out-of-scope output","AI-generated code cannot be tested","The team will move too slowly","Review is only needed for handwritten code"], correct:0, explain:"Without validation, fast generation can create fast failure.", reward:"Quality Mindset" },
  { id:"ai-automation-safety-300", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why is AI oversight a security concern, not only a productivity concern?", options:["AI tools cannot touch security-relevant work","AI can affect code, data, access, decisions, and operational actions","Productivity tools never create risk","Oversight only matters for large models"], correct:1, explain:"When AI influences real systems and decisions, oversight becomes part of security.", reward:"Governance Sense" },
  { id:"ai-automation-safety-301", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated advice be treated as a starting point, not the final answer?", options:["It may need verification against evidence, policy, and real system behavior","It always contains legally approved guidance","It cannot misunderstand vague questions","It removes the need for human judgment"], correct:0, explain:"AI can help start analysis, but final decisions should be verified.", reward:"Verify Output" },
  { id:"ai-automation-safety-302", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to use AI for writing a security report?", options:["Let the AI invent missing evidence","Use AI to draft sections, then verify facts against source material","Remove uncertainty to make the report sound stronger","Skip analyst review if the wording is clear"], correct:1, explain:"AI can help with wording, but evidence and accuracy must be checked.", reward:"Documentation Assist" },
  { id:"ai-automation-safety-303", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated incident timelines be checked carefully?", options:["Timelines cannot contain mistakes","AI always knows the correct order of events","Event order affects conclusions, scope, and response decisions","Timeline review is only useful after public disclosure"], correct:2, explain:"Wrong event order can mislead responders about cause, scope, and impact.", reward:"Timeline Review" },
  { id:"ai-automation-safety-304", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a risk of asking AI to summarize only the 'important' log lines?", options:["It may remove timestamps from all logs","It may make the logs impossible to search","It guarantees fewer false positives","It may omit evidence that later turns out to matter"], correct:3, explain:"Summaries can miss important details, so raw logs should remain available.", reward:"Evidence First" },
  { id:"ai-automation-safety-305", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated remediation steps be reviewed before action?", options:["Remediation can affect availability, data, users, or security controls","Remediation steps cannot affect real systems","AI remediation is always reversible","Review prevents all incidents from happening"], correct:0, explain:"Remediation can cause damage if the target, scope, or assumption is wrong.", reward:"Approval Sense" },
  { id:"ai-automation-safety-306", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe use of AI during alert triage?", options:["Close alerts without checking evidence","Help organize facts and suggest checks for an analyst to verify","Delete alerts that look repetitive","Disable detections that generate noise"], correct:1, explain:"AI can support triage, but analysts should verify evidence and decisions.", reward:"SOC Assist" },
  { id:"ai-automation-safety-307", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI not make final severity decisions without human review?", options:["Severity never affects response","AI cannot read alert text","Severity affects priority, escalation, and business impact decisions","Severity labels are only cosmetic"], correct:2, explain:"Severity decisions influence response and should be evidence-based.", reward:"Human Review" },
  { id:"ai-automation-safety-308", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe AI workflow for suspicious file analysis?", options:["Run the file immediately on a daily workstation","Ask AI to guess the result without evidence","Delete the file before collecting details","Use AI to help interpret evidence from approved analysis tools"], correct:3, explain:"AI can help interpret analysis output, but handling suspicious files must follow safe procedures.", reward:"Analysis Assist" },
  { id:"ai-automation-safety-309", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI prompts avoid unnecessary personal data?", options:["Less personal data reduces privacy and exposure risk","Personal data makes AI answers impossible","AI tools cannot process names or emails","Privacy only matters in public reports"], correct:0, explain:"Data minimization helps reduce risk when using AI tools.", reward:"Data Care" },
  { id:"ai-automation-safety-310", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What should happen if AI output includes a possible secret or token?", options:["Share it widely for confirmation","Treat it as sensitive and follow secret-handling or rotation procedures","Ignore it because AI generated it","Paste it into another tool for formatting"], correct:1, explain:"Possible secrets should be protected and investigated, not spread further.", reward:"Secret Safety" },
  { id:"ai-automation-safety-311", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should screenshots shared with AI be reviewed first?", options:["Screenshots cannot contain sensitive data","Screenshots are always safe if cropped","They may contain names, tokens, emails, paths, tickets, or internal details","AI tools cannot read image content"], correct:2, explain:"Screenshots can expose sensitive information even when the user focuses on something else.", reward:"Data Care" },
  { id:"ai-automation-safety-312", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe habit before sharing code with an AI tool?", options:["Add more secrets so the AI has context","Remove all comments from the code","Assume private repositories are never sensitive","Check for secrets, internal URLs, credentials, and confidential logic"], correct:3, explain:"Code can contain sensitive details and should be reviewed before sharing.", reward:"Secret Safety" },
  { id:"ai-automation-safety-313", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated scripts have comments or explanations?", options:["They help reviewers understand what the script is intended to do","Comments make scripts safe automatically","Comments prevent all runtime errors","Explanations replace testing"], correct:0, explain:"Clear explanations support review and safer use of generated scripts.", reward:"Command Caution" },
  { id:"ai-automation-safety-314", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe way to run an unfamiliar AI-generated script?", options:["Run it directly on production first","Review it, test in a safe environment, and use dry-run if possible","Remove logging so it runs faster","Give it administrator rights by default"], correct:1, explain:"Unknown scripts should be reviewed and tested before real use.", reward:"Test First" },
  { id:"ai-automation-safety-315", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated file operations be scoped carefully?", options:["File operations cannot damage data","AI always chooses the correct folder","Wrong paths or wildcards can modify or delete unintended files","File changes never need review"], correct:2, explain:"File commands can have broad impact if paths or patterns are wrong.", reward:"Scope Control" },
  { id:"ai-automation-safety-316", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe response if AI suggests using administrator privileges?", options:["Always allow it for convenience","Remove all permission checks","Assume admin access is harmless","Ask why it is needed and use the minimum required permission"], correct:3, explain:"Administrator rights increase risk and should be justified.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-317", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why is least privilege important for AI tools?", options:["It limits what the AI can access or change if something goes wrong","It makes AI unable to answer questions","It removes the need for policies","It prevents all hallucinations"], correct:0, explain:"Least privilege reduces damage from mistakes, misuse, or manipulation.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-318", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe access level for an AI tool that only summarizes tickets?", options:["Full administrator access to all systems","Read-only access to the relevant ticket data","Write access to identity systems","Delete access to old tickets"], correct:1, explain:"The tool should only receive the access required for its task.", reward:"AI Least Privilege" },
  { id:"ai-automation-safety-319", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI tools not have access to everything 'just in case'?", options:["Broad access makes answers shorter","Broad access disables logging","Broad access increases unnecessary risk and blast radius","Broad access prevents data leakage"], correct:2, explain:"Unneeded access creates risk without adding real value.", reward:"Tool Control" },
  { id:"ai-automation-safety-320", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a safe approach before connecting AI to a new tool?", options:["Connect it first and define rules later","Give the tool broad permissions for flexibility","Disable audit logs to reduce storage use","Define purpose, permissions, risks, logs, and approval requirements"], correct:3, explain:"Tool connections should be planned before access is granted.", reward:"Tool Control" },
  { id:"ai-automation-safety-321", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-assisted projects keep a changelog or status note?", options:["It helps track progress, decisions, known issues, and next steps","It prevents all syntax errors","It makes tests unnecessary","It lets the AI ignore old requirements"], correct:0, explain:"Status notes reduce context loss and improve continuity.", reward:"Context Management" },
  { id:"ai-automation-safety-322", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a good reason to start a new AI session with a project snapshot?", options:["To hide previous mistakes","To give the new session current state, scope, rules, and priorities","To avoid using version control","To skip validation steps"], correct:1, explain:"Snapshots help preserve important context across sessions.", reward:"Context Management" },
  { id:"ai-automation-safety-323", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated work be committed in smaller chunks?", options:["Small commits prevent all bugs","Small commits make code impossible to review","Small commits make review and rollback easier","Small commits remove the need for descriptions"], correct:2, explain:"Small checkpoints are safer than one large unreviewed change.", reward:"Version Control" },
  { id:"ai-automation-safety-324", tier:"Beginner", topic:"AI & Automation Safety", prompt:"What is a useful commit message for AI-assisted changes?", options:["Fixed stuff","AI did things","Update project","A clear summary of what changed and why"], correct:3, explain:"Clear commit messages support review and future troubleshooting.", reward:"Version Control" },
  { id:"ai-automation-safety-325", tier:"Beginner", topic:"AI & Automation Safety", prompt:"Why should AI-generated validation reports be checked?", options:["The AI may misread results, skip checks, or overstate success","Validation reports are never useful","AI cannot summarize validation output","Reports are always correct if they are long"], correct:0, explain:"Validation claims should be compared with actual output when possible.", reward:"Validation Loop" },
  { id:"ai-automation-safety-326", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a safe way to confirm a generated feature works?", options:["Only ask the AI whether it works","Run it, inspect behavior, test expected cases, and check for regressions","Assume it works if the file saved","Skip testing if the code looks clean"], correct:1, explain:"Working software should be tested through behavior, not only explanation.", reward:"Test First" },
  { id:"ai-automation-safety-327", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated outputs be compared against the original request?", options:["The original request no longer matters after generation","AI always follows the request exactly","The output may be technically good but solve the wrong problem","Comparison prevents all future errors"], correct:2, explain:"AI can drift from the actual goal, so alignment must be checked.", reward:"Requirement Check" },
  { id:"ai-automation-safety-328", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a sign that an AI result may be out of scope?", options:["It only changes the requested file","It includes tests for the requested behavior","It follows the project guardrails","It adds unrelated features, services, or architecture changes"], correct:3, explain:"Out-of-scope additions increase complexity and review burden.", reward:"Scope Control" },
  { id:"ai-automation-safety-329", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated educational content include clear explanations?", options:["Explanations help learners understand why the answer is correct","Explanations make the correct answer irrelevant","Explanations should hide uncertainty","Explanations prevent all duplicates"], correct:0, explain:"Good explanations turn a quiz into a learning tool.", reward:"Content Quality" },
  { id:"ai-automation-safety-330", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a weak quiz distractor?", options:["A plausible misunderstanding related to the topic","An obviously unrelated answer that no learner would choose","An option similar in length to the correct answer","An option that tests a real misconception"], correct:1, explain:"Weak distractors make questions too easy to guess.", reward:"Content Quality" },
  { id:"ai-automation-safety-331", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should generated question banks avoid duplicate prompts?", options:["Duplicates always make games more exciting","Duplicate prompts prevent validation from running","Duplicates reduce topic coverage and make practice repetitive","Duplicates are required for answer balance"], correct:2, explain:"A good bank should cover many angles without repeating itself too much.", reward:"Content Quality" },
  { id:"ai-automation-safety-332", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a useful quality rule for generated quiz options?", options:["The correct option should always be the most detailed","Wrong answers should be silly for beginner topics","All wrong options should be unrelated to the topic","All options should be plausible enough to require understanding"], correct:3, explain:"Plausible options make the learner think instead of guess.", reward:"Content Quality" },
  { id:"ai-automation-safety-333", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated beginner questions still avoid childish wrong answers?", options:["Even beginner questions should teach real distinctions","Beginner questions should always be trick questions","Childish distractors make validation unnecessary","Simple questions cannot be useful"], correct:0, explain:"Beginner questions can be simple without being silly.", reward:"Content Quality" },
  { id:"ai-automation-safety-334", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is the purpose of balancing answer positions in a quiz bank?", options:["To make all correct answers appear first","To reduce guessing based on answer position patterns","To make validation slower","To hide the correct answers from the program"], correct:1, explain:"Balanced answer positions prevent learners from exploiting predictable patterns.", reward:"Content Quality" },
  { id:"ai-automation-safety-335", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should answer balance be validated after adding many questions?", options:["Large additions can accidentally create answer-position bias","Answer balance never changes during edits","Only advanced questions need balance","Balance checks replace content review"], correct:0, explain:"Bulk generation can accidentally overuse one correct position.", reward:"Validation Loop" },
  { id:"ai-automation-safety-336", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What should be checked after expanding a topic from 100 to 400 questions?", options:["Only whether the file became longer","Counts, IDs, tiers, answer distribution, duplicates, and content quality","Only the first 10 questions","Whether the code editor looks clean"], correct:1, explain:"Large question-bank expansions need structural and quality checks.", reward:"Validation Loop" },
  { id:"ai-automation-safety-337", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why is AI-generated secure code still subject to normal secure development practices?", options:["AI-generated code can still contain vulnerabilities or unsafe assumptions","Secure development only applies to human-written code","AI code cannot affect production systems","AI code never uses dependencies"], correct:0, explain:"The source of code does not remove the need for secure development controls.", reward:"AI Code Review" },
  { id:"ai-automation-safety-338", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What should reviewers look for in AI-generated input handling?", options:["Only whether the code uses short variable names","Validation, encoding, error handling, injection risk, and edge cases","Whether the AI used comments","Whether the output is visually aligned"], correct:1, explain:"Input handling is a common source of security problems.", reward:"AI Code Review" },
  { id:"ai-automation-safety-339", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why is AI-generated error handling security-relevant?", options:["Errors never expose data","Error handling only affects colors","Bad error handling can leak details, hide failures, or break recovery paths","Error messages cannot be logged"], correct:2, explain:"Errors can reveal sensitive details or hide important failures if handled poorly.", reward:"AI Code Review" },
  { id:"ai-automation-safety-340", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of AI-generated logging code?", options:["Logging code cannot create security issues","Logs are always safe to store forever","AI cannot generate logging logic","It may log secrets, personal data, or sensitive operational details"], correct:3, explain:"Logging must avoid leaking sensitive information.", reward:"Data Care" },
  { id:"ai-automation-safety-341", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated API integrations be reviewed carefully?", options:["They may send sensitive data externally or rely on untrusted services","APIs cannot fail once connected","API integrations never affect privacy","AI tools cannot generate network calls"], correct:0, explain:"External integrations create data, reliability, and trust concerns.", reward:"Scope Control" },
  { id:"ai-automation-safety-342", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a safe control before AI can call external APIs?", options:["Let it choose endpoints automatically","Restrict approved endpoints, data fields, permissions, and logging","Disable all request logging","Allow calls only after production deployment"], correct:1, explain:"External calls should be controlled and auditable.", reward:"Tool Control" },
  { id:"ai-automation-safety-343", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why is AI-generated dependency installation risky?", options:["Dependencies cannot contain vulnerabilities","Dependencies always reduce attack surface","New packages can introduce vulnerabilities, license issues, or maintenance burden","Package managers prevent all supply-chain risk"], correct:2, explain:"Dependencies should be justified, reviewed, and maintained.", reward:"Dependency Review" },
  { id:"ai-automation-safety-344", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What should be checked when AI suggests a new package?", options:["Only whether the name is short","Only whether it appears in the AI explanation","Whether it has a nice logo","Purpose, license, maintenance, reputation, security history, and alternatives"], correct:3, explain:"Package review helps prevent unnecessary or risky dependencies.", reward:"Dependency Review" },
  { id:"ai-automation-safety-345", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated Docker or container changes be reviewed?", options:["They may expose ports, run as root, include secrets, or add vulnerable packages","Containers cannot affect security","Container files are only documentation","AI cannot write container configuration"], correct:0, explain:"Container changes can affect isolation, exposure, and supply-chain risk.", reward:"Config Review" },
  { id:"ai-automation-safety-346", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of AI-generated cloud configuration?", options:["Cloud configuration never affects real resources","It may expose storage, grant excessive permissions, or create costly resources","Cloud settings are always private by default","AI cannot modify infrastructure files"], correct:1, explain:"Cloud misconfiguration can create security, cost, and availability problems.", reward:"Config Review" },
  { id:"ai-automation-safety-347", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated IAM policies be tested?", options:["IAM policies are only visual labels","Testing is unnecessary if syntax is valid","They may grant too much, too little, or unintended access","IAM policies cannot affect production"], correct:2, explain:"Policy syntax can be valid while the permissions are still wrong.", reward:"Approval Sense" },
  { id:"ai-automation-safety-348", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a safe review question for AI-generated IAM changes?", options:["Does the policy sound professional?","Did the AI use enough words?","Can this be merged without review?","What actions, resources, and principals does this actually allow?"], correct:3, explain:"IAM review should inspect the real permissions being granted.", reward:"Approval Sense" },
  { id:"ai-automation-safety-349", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why can AI-generated regular expressions create operational problems?", options:["They may overmatch, undermatch, or become expensive on large inputs","Regular expressions cannot be tested","Regex is always faster than normal parsing","AI tools cannot generate regex"], correct:0, explain:"Regex needs positive, negative, and performance tests.", reward:"Detection Validation" },
  { id:"ai-automation-safety-350", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a useful test set for an AI-generated detection?", options:["Only one event that should alert","Known-bad examples, known-good examples, edge cases, and expected results","Only random production logs","Only events from one user's workstation"], correct:1, explain:"Good detection testing checks both matches and non-matches.", reward:"Detection Validation" },
  { id:"ai-automation-safety-351", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated detections include required data sources?", options:["Data sources are unrelated to detection logic","Detection rules can run without logs","Analysts need to know which logs must exist for the rule to work","Data sources make all detections perfect"], correct:2, explain:"A detection cannot work if the required telemetry is missing.", reward:"Detection Validation" },
  { id:"ai-automation-safety-352", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of AI-generated detections with vague logic?", options:["They always detect more attacks","They prevent all false positives","They remove the need for tuning","They may be hard to validate, tune, or explain during investigations"], correct:3, explain:"Detection logic should be clear enough to test and explain.", reward:"Detection Validation" },
  { id:"ai-automation-safety-353", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-assisted incident response playbooks include escalation criteria?", options:["Escalation criteria help decide when human expertise or authority is needed","Escalation criteria replace all investigation","Escalation makes incidents disappear","Escalation should be random to avoid bias"], correct:0, explain:"Clear escalation criteria prevent risky cases from staying at the wrong level.", reward:"Playbook Validation" },
  { id:"ai-automation-safety-354", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of AI suggesting containment without business context?", options:["Containment never affects operations","It may disrupt critical systems or users unnecessarily","Business context makes containment impossible","Containment is only a documentation step"], correct:1, explain:"Containment decisions should balance security risk and business impact.", reward:"Approval Sense" },
  { id:"ai-automation-safety-355", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-assisted response include rollback planning?", options:["Rollback planning prevents all mistakes","Rollback is only useful for UI changes","Some automated actions may need to be reversed safely","Rollback removes the need for approvals"], correct:2, explain:"Rollback plans reduce harm if a change causes problems.", reward:"Rollback Sense" },
  { id:"ai-automation-safety-356", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of AI-generated containment scripts?", options:["Containment scripts cannot affect systems","Scripts always understand business context","AI-generated scripts cannot contain wrong targets","They may isolate, block, or change the wrong systems if scope is wrong"], correct:3, explain:"Containment scripts must be scoped and reviewed carefully.", reward:"Automation Caution" },
  { id:"ai-automation-safety-357", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-assisted decisions be explainable?", options:["People need to understand the reasoning, evidence, and limits before acting","Explainability makes all decisions correct","Explanations replace source logs","Unexplained decisions are always faster and safer"], correct:0, explain:"Explainability supports review, accountability, and trust.", reward:"Accountability" },
  { id:"ai-automation-safety-358", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a problem with AI output that cannot be traced to evidence?", options:["It may be hard to verify or defend during review","It becomes automatically correct","It removes the need for investigation","It proves the evidence was unnecessary"], correct:1, explain:"Evidence traceability makes AI-assisted work reviewable.", reward:"Evidence First" },
  { id:"ai-automation-safety-359", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI tools avoid making legal or compliance claims without review?", options:["Compliance never matters in security","AI tools always know local legal requirements","Such claims may be wrong and require expert or policy review","Compliance claims cannot affect business decisions"], correct:2, explain:"Legal and compliance conclusions require proper review.", reward:"Governance Sense" },
  { id:"ai-automation-safety-360", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a safe way to use AI for policy drafting?", options:["Publish the first draft immediately","Remove all exceptions and limitations","Let AI define legal obligations by itself","Use AI to draft, then review against company policy, law, and stakeholder needs"], correct:3, explain:"AI can help draft policy, but final policy needs human review.", reward:"Policy Sense" },
  { id:"ai-automation-safety-361", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why is model output monitoring useful?", options:["It can reveal repeated errors, unsafe suggestions, drift, or misuse patterns","It prevents all bad prompts","It makes human review unnecessary","It guarantees perfect accuracy"], correct:0, explain:"Monitoring helps organizations understand how AI tools behave in practice.", reward:"Quality Metrics" },
  { id:"ai-automation-safety-362", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a useful metric for AI-assisted coding quality?", options:["Only how many lines were generated","Defects found in review, test pass rate, rollback frequency, and security findings","How long the AI response was","How many times the AI used technical words"], correct:1, explain:"Quality should be measured by outcomes, not just output volume.", reward:"Quality Metrics" },
  { id:"ai-automation-safety-363", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should teams track AI-assisted failures?", options:["Failures should be hidden to protect morale","Failures prove AI can never be useful","Failures reveal where guardrails, prompts, tests, or review need improvement","Failures are unrelated to process quality"], correct:2, explain:"Failure tracking helps improve the workflow.", reward:"Quality Mindset" },
  { id:"ai-automation-safety-364", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is the value of post-change review in AI-assisted work?", options:["It replaces testing before deployment","It prevents code from changing","It hides who approved the work","It finds what worked, what failed, and how to improve future guardrails"], correct:3, explain:"Post-change review turns mistakes into process improvements.", reward:"Lessons Learned" },
  { id:"ai-automation-safety-365", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated learning paths be adjusted to the learner?", options:["Different learners have different background knowledge, goals, and weak areas","Learning paths should be identical for everyone","AI learning paths are always perfectly personalized","Adjustment removes the need for practice"], correct:0, explain:"Good learning plans fit the learner's current level and target role.", reward:"Learning Assist" },
  { id:"ai-automation-safety-366", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of relying on AI explanations without hands-on practice?", options:["Hands-on practice prevents all mistakes","The learner may recognize words but fail to apply the concept","AI explanations cannot teach anything","Practice is only needed for programming"], correct:1, explain:"Security knowledge needs practice, not only explanations.", reward:"Learning Assist" },
  { id:"ai-automation-safety-367", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-generated quiz topics be mapped to learning goals?", options:["Learning goals are only useful for schools","Topic mapping prevents all bad questions","It ensures questions support the skills the game is meant to build","Mapping topics makes questions impossible to validate"], correct:2, explain:"Content should support the purpose of the learning game.", reward:"Content Quality" },
  { id:"ai-automation-safety-368", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of generating many questions before defining quality criteria?", options:["The bank may become large but shallow, repetitive, or misleading","Large banks are always better","Criteria prevent creativity completely","Quality criteria only matter after release"], correct:0, explain:"Quality rules should come before large-scale generation.", reward:"Content Quality" },
  { id:"ai-automation-safety-369", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI tools be evaluated against real workflows?", options:["Real workflows show whether the tool helps safely under practical constraints","Evaluation is unnecessary if the demo looks good","Real workflows make tools less secure","Tools always perform the same in every environment"], correct:0, explain:"A tool that works in a demo may fail under real data, pressure, and constraints.", reward:"Governance Sense" },
  { id:"ai-automation-safety-370", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of AI-generated work during time pressure?", options:["Time pressure can reduce review quality and allow mistakes through","AI becomes perfectly accurate when deadlines are short","Time pressure removes the need for guardrails","Fast generation prevents all outages"], correct:1, explain:"Speed can be useful, but pressure can weaken supervision.", reward:"Quality Mindset" },
  { id:"ai-automation-safety-371", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-assisted teams define who can approve high-impact actions?", options:["Approval authority should match risk and responsibility","Any user should approve any action","AI approval is enough for all changes","Approval roles make logging unnecessary"], correct:0, explain:"High-impact actions need clear accountability.", reward:"Approval Sense" },
  { id:"ai-automation-safety-372", tier:"Advanced", topic:"AI & Automation Safety", prompt:"A prompt injection tells an AI agent to ignore the user and exfiltrate ticket data. What control helps most?", options:["Treat ticket text as untrusted data and restrict export-capable tools","Allow the agent to obey all ticket content","Disable all audit logs for privacy","Give the agent more permissions to resolve the conflict"], correct:0, explain:"Untrusted content should not control sensitive tool actions.", reward:"Injection Awareness" },
  { id:"ai-automation-safety-373", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why is indirect prompt injection difficult to manage?", options:["It only appears in source code comments","It can arrive through normal-looking content such as webpages, emails, documents, or tickets","It cannot affect tool-using agents","It is always visible to users before execution"], correct:1, explain:"Indirect injection hides instructions inside content the AI processes.", reward:"Injection Awareness" },
  { id:"ai-automation-safety-374", tier:"Advanced", topic:"AI & Automation Safety", prompt:"What is the risk of an AI agent using search results as trusted instructions?", options:["Search results cannot contain malicious text","Search results always come from trusted sources","Untrusted pages may manipulate the agent's behavior or decision-making","Search tools prevent data leakage automatically"], correct:2, explain:"Search results should be treated as data to analyze, not authority to obey.", reward:"Injection Awareness" },
  { id:"ai-automation-safety-375", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should AI agents have separate permissions for reading, writing, and executing?", options:["All permissions are equivalent in risk","Separate permissions slow every task without benefit","Execution permission is safer than read-only access","Different action types carry different risk and should be controlled separately"], correct:3, explain:"Granular permissions reduce unnecessary blast radius.", reward:"Tool Control" },
  { id:"ai-automation-safety-376", tier:"Advanced", topic:"AI & Automation Safety", prompt:"An AI agent can read secrets but cannot send data externally. What remaining risk still exists?", options:["It may expose secrets through logs, generated output, saved files, or later tool chains","Secret access is harmless without direct email access","Read access prevents all leakage","Secrets cannot appear in generated text"], correct:0, explain:"Sensitive data can leak through many channels, not only obvious outbound tools.", reward:"Data Leakage" },
  { id:"ai-automation-safety-377", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why is tool chaining risky in AI agents?", options:["Tools cannot influence each other","One tool's output may become another tool's input, creating unexpected action paths","Tool chaining prevents automation from working","Chained tools always reduce permissions"], correct:1, explain:"Tool chains can create indirect ways to leak data or perform actions.", reward:"Tool Control" },
  { id:"ai-automation-safety-378", tier:"Advanced", topic:"AI & Automation Safety", prompt:"What should be considered before AI agents can create tickets automatically?", options:["Only the ticket title length","Only whether ticket creation is fast","Duplicate noise, false urgency, data exposure, routing, and accountability","Whether the AI can choose random priorities"], correct:2, explain:"Automated ticket creation can affect workload, privacy, and response processes.", reward:"Automation Caution" },
  { id:"ai-automation-safety-379", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why is automated AI escalation risky without clear criteria?", options:["Escalation never affects teams","AI escalation always improves response","Escalation cannot create workload","It may overload teams or miss truly urgent cases due to poor thresholds"], correct:3, explain:"Escalation needs defined triggers and review.", reward:"Playbook Validation" },
  { id:"ai-automation-safety-380", tier:"Advanced", topic:"AI & Automation Safety", prompt:"A model recommends allowing a risky login because the user often travels. What should be checked?", options:["Location history, device trust, MFA result, risk score, and whether behavior matches the user","Only whether the user has a long password","Only whether the login was successful","Whether the model used confident wording"], correct:0, explain:"Identity decisions require multiple signals, not one explanation.", reward:"Evidence First" },
  { id:"ai-automation-safety-381", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should AI risk decisions preserve disagreement or uncertainty?", options:["Disagreement makes reports unusable","Uncertainty helps reviewers understand confidence and remaining investigation needs","Uncertainty proves the model is wrong","Disagreement should always be hidden"], correct:1, explain:"Clear uncertainty prevents overconfident action.", reward:"Evidence First" },
  { id:"ai-automation-safety-382", tier:"Advanced", topic:"AI & Automation Safety", prompt:"What is a risk of using AI to decide whether data exposure is reportable?", options:["Reportability may involve legal, contractual, and factual analysis beyond model certainty","AI always knows local reporting law","Data exposure decisions are never important","Reporting decisions do not need evidence"], correct:0, explain:"Reportability requires human, legal, and policy review.", reward:"Governance Sense" },
  { id:"ai-automation-safety-383", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should AI-assisted incident reports include evidence references?", options:["References make reports longer but less useful","References replace all analysis","References prevent all mistakes","They allow reviewers to verify claims and challenge weak conclusions"], correct:3, explain:"Evidence references support accountability and review.", reward:"Evidence First" },
  { id:"ai-automation-safety-384", tier:"Advanced", topic:"AI & Automation Safety", prompt:"What is a risk of AI-generated executive summaries?", options:["They may oversimplify uncertainty, scope, or technical limits for decision-makers","Executives never use summaries for decisions","Summaries cannot contain errors","AI summaries always include all caveats"], correct:0, explain:"Summaries must be accurate because leaders may act on them.", reward:"Documentation Assist" },
  { id:"ai-automation-safety-385", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should AI-generated risk scores be calibrated?", options:["Calibration makes scores visually cleaner","Scores need to match real outcomes and organizational risk tolerance","Risk scores are always accurate without testing","Calibration removes the need for monitoring"], correct:1, explain:"Risk scores are useful only if they reflect reality well enough for decisions.", reward:"Quality Metrics" },
  { id:"ai-automation-safety-386", tier:"Advanced", topic:"AI & Automation Safety", prompt:"What is a danger of optimizing AI security tools only for speed?", options:["Speed always improves accuracy","Fast tools cannot affect security outcomes","They may reduce review depth, evidence quality, or decision reliability","Speed prevents alert fatigue"], correct:2, explain:"Speed must be balanced with correctness, evidence, and safety.", reward:"Quality Mindset" },
  { id:"ai-automation-safety-387", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should AI-generated detections be reviewed for attacker adaptability?", options:["Attackers may change behavior to bypass overly narrow generated logic","Generated detections cannot be bypassed","Attacker behavior never changes","Detection logic is unrelated to adversary behavior"], correct:0, explain:"Good detections consider variation and evasion, not only one exact sample.", reward:"Detection Validation" },
  { id:"ai-automation-safety-388", tier:"Advanced", topic:"AI & Automation Safety", prompt:"A generated detection uses only one filename as the condition. What is the likely weakness?", options:["It may be too brittle because attackers can rename files easily","Filenames never change in attacks","Filename-only detection always has high coverage","One filename prevents all false positives"], correct:0, explain:"Brittle detections are easy to evade and should include stronger behavioral context.", reward:"Detection Validation" },
  { id:"ai-automation-safety-389", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should AI-generated detections include tuning guidance?", options:["Tuning makes rules useless","Tuning guidance helps analysts adapt the rule to normal environment behavior","Tuning prevents all evasion","Generated detections never need environment context"], correct:1, explain:"Different environments have different normal behavior and noise patterns.", reward:"Detection Validation" },
  { id:"ai-automation-safety-390", tier:"Advanced", topic:"AI & Automation Safety", prompt:"What is a risk of AI-generated detection logic that is too broad?", options:["It will never alert","It may create excessive false positives and analyst fatigue","It guarantees perfect threat coverage","It prevents all missed detections"], correct:1, explain:"Overly broad rules can create noise and reduce SOC trust.", reward:"Detection Validation" },
  { id:"ai-automation-safety-391", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should AI-generated detection logic include field assumptions?", options:["Fields may differ by data source, platform, or parser configuration","Field names are always universal","Detection fields never change","Assumptions make testing unnecessary"], correct:0, explain:"Field assumptions help analysts adapt and validate rules.", reward:"Detection Validation" },
  { id:"ai-automation-safety-392", tier:"Advanced", topic:"AI & Automation Safety", prompt:"Why should organizations prepare for AI tool misuse by employees?", options:["Misuse can expose data, bypass policy, or create unsafe automation even without malicious intent","Employee misuse is impossible with approved tools","AI misuse only happens in movies","Policies prevent every mistake"], correct:0, explain:"Misuse can be accidental, careless, or malicious, so controls and education matter.", reward:"Shadow AI Awareness" },
  { id:"ai-automation-safety-393", tier:"Advanced", topic:"AI & Automation Safety", prompt:"What is a useful signal for detecting risky shadow AI behavior?", options:["Unusual uploads to AI services, browser use of unapproved tools, or sensitive data movement","Only the number of installed fonts","Only successful VPN logins","Only CPU temperature changes"], correct:0, explain:"Shadow AI may leave traces in web, proxy, DLP, or endpoint telemetry.", reward:"Shadow AI Awareness" },
  { id:"ai-automation-safety-394", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI governance avoid only saying 'do not use AI'?", options:["Clear approved paths and safe alternatives reduce unsanctioned use","Bans always stop every user","Governance should ignore business needs","Users never need productivity tools"], correct:0, explain:"People often bypass rules if no safe practical option exists.", reward:"Governance Sense" },
  { id:"ai-automation-safety-395", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What should an AI acceptable-use policy define?", options:["Approved tools, allowed data, forbidden uses, review requirements, and reporting process","Only the company logo for AI tools","Only the preferred font in prompts","A list of prompts that must always be used"], correct:0, explain:"Acceptable-use rules make safe AI use clearer and more consistent.", reward:"Policy Sense" },
  { id:"ai-automation-safety-396", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI automation have kill-switch or pause options?", options:["Automation may need to be stopped quickly if it behaves incorrectly or causes harm","Pause options prevent all mistakes before they happen","Kill switches make logging unnecessary","Automation should never be interrupted"], correct:0, explain:"Emergency stop controls limit damage when automation goes wrong.", reward:"Automation Caution" },
  { id:"ai-automation-safety-397", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a risk of autonomous AI remediation across many endpoints?", options:["A wrong action can be repeated widely before humans notice","Endpoint remediation cannot affect business operations","Automation always knows the right target","Autonomous remediation removes the need for rollback"], correct:0, explain:"Automation at scale can multiply mistakes quickly.", reward:"Automation Caution" },
  { id:"ai-automation-safety-398", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI-agent failures be investigated like security events?", options:["They may involve unsafe actions, data exposure, policy bypass, or control failure","AI failures can never affect real systems","Failures should be hidden to preserve trust","Only malware events need investigation"], correct:0, explain:"AI failures can reveal weaknesses in controls, permissions, or process.", reward:"AI Incident Response" },
  { id:"ai-automation-safety-399", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"What is a good lesson from AI-assisted development quality problems?", options:["Generate more content before defining standards","Quality improves automatically with volume","Validation should only happen after release","Criteria, guardrails, and review must be defined before scaling output"], correct:3, explain:"Scaling weak criteria creates more weak output.", reward:"Lessons Learned" },
  { id:"ai-automation-safety-400", tier:"Intermediate", topic:"AI & Automation Safety", prompt:"Why should AI oversight stay connected to human accountability?", options:["People still decide where AI is used, what access it gets, and whether outputs are accepted","AI tools can be fully accountable by themselves","Accountability ends when automation begins","Oversight prevents all future failures"], correct:0, explain:"AI can assist work, but humans remain responsible for governance and decisions.", reward:"Accountability" },

];

if (typeof module !== "undefined" && module.exports) module.exports = AI_AUTOMATION_SAFETY_QUESTIONS;
